def digest(path):
    value = hashlib.sha256()
    with Path(path).open('rb') as stream:
        for block in iter(lambda: stream.read(1024 * 1024), b''):
            value.update(block)
    return value.hexdigest()


def effective_node_sha256(args):
    return args.node_sha256 if args.current_host_profile is not None else NODE_SHA256


def node_pin_matches(node, expected_sha256):
    return digest(node) == expected_sha256




def validate_v19_summary_pins(source, digest_file):
    # A prepared delta is never an authorization to qualify unfrozen bytes.
    if any(not isinstance(value, str) or not re.fullmatch(r'[a-f0-9]{64}', value)
           for value in V19_SUMMARY_PINS.values()):
        raise RuntimeError('V19 source pins are not frozen')
    for name, expected in V19_SUMMARY_PINS.items():
        if digest_file(source / name) != expected:
            raise RuntimeError('Pinned V19 source changed: ' + name)
    return tuple(V19_SUMMARY_PINS)


def cleanup_v19_files_root(target, identity, runtime, name='v19-owned-files'):
    if target is None:
        return True
    if name not in ('v19-owned-files','v44-owned-files') or target != runtime / name or target.is_symlink():
        raise RuntimeError('V19 files cleanup authority mismatch')
    if not target.exists():
        return True
    current = target.lstat()
    if identity is None or (current.st_dev, current.st_ino, current.st_uid) != identity:
        raise RuntimeError('V19 files cleanup identity changed')
    if current.st_uid != os.getuid() or not stat.S_ISDIR(current.st_mode):
        raise RuntimeError('V19 files cleanup ownership mismatch')
    shutil.rmtree(target)
    return not target.exists() and not target.is_symlink()


