def validate_v07_upload_inputs(args,source):
    for name,expected in V07_UPLOAD_PINS.items():
        if digest(source/name)!=expected:raise RuntimeError('Pinned V07 source changed: '+name)
    for kind in ('native','package'):
        target=Path(getattr(args,'v07_'+kind+'_result') or '')
        expected=getattr(args,'v07_'+kind+'_result_sha256')
        if not target.is_absolute() or target.resolve().is_relative_to(source) or not re.fullmatch('[a-f0-9]{64}',expected or ''):
            raise RuntimeError('Private hash-bound V07 '+kind+' result required')
        value=mail_inline_private_json(target,4*1024*1024)
        if digest(target)!=expected:raise RuntimeError('Private hash-bound V07 '+kind+' result required')
        if any(value.get(key) is not True for key in ('sourceUnchanged',)) or not value.get('sourceHashes'):
            raise RuntimeError('Unchanged V07 '+kind+' proof required')
        for name,sha in value['sourceHashes'].items():
            if digest(source/name)!=sha:raise RuntimeError('V07 '+kind+' source incompatible: '+name)
        if kind=='native':
            if any(value.get(key) is not True for key in ('passed','dependenciesUnchanged','containerAbsent','childGroupsAbsent','polyglotPreviewControlled')) or value.get('cleanupErrors')!=[] or type(value.get('exitCode')) is not int or value['exitCode']!=0 or type(value.get('expectedTests')) is not int or value['expectedTests']!=2 or any(value.get(key) is not False for key in ('sourceCopies','actualModel','browser','judgeOrCredit')) or value.get('sourceHashesAfter')!=value['sourceHashes'] or value.get('fixture')!='tests/postgres/secureshopV06UploadAssessmentNative.integration.test.js':
                raise RuntimeError('Complete controlled V07 PostgreSQL proof required')
            tap=target.parent/'test.stdout.log'
            if tap.is_symlink() or not tap.is_file() or tap.stat().st_uid!=os.getuid() or tap.stat().st_mode&0o777!=0o600 or tap.stat().st_size>1024*1024 or digest(tap)!=value.get('stdoutSha256'):
                raise RuntimeError('Original controlled V07 PostgreSQL TAP required')
            counts=complete_tap_counts(tap.read_text(),'V07 native admission',[
                'native V06 upload defaults are qualified/disabled and preserve exact pending promotion and populated instructor state on no-op reseed',
                'native V06 assessment binds original PG turn/trace/effect/serve and fences sibling/reset/recovery'])
            if counts['tests']!=2:raise RuntimeError('Two original V07 native assertions required')
        else:
            if value.get('status')!='passed' or value.get('sourceCopy') is not False or value.get('nodeUnchanged') is not True or value.get('cleanup',{}).get('errors')!=[] or any(v is not True for k,v in value.get('cleanup',{}).items() if k!='errors'):
                raise RuntimeError('Complete owned V07 package cleanup proof required')
            proof=value.get('modes',{}).get('upload-preview',{})
            flags=('fullDecodeBounded','sameByteExecution','externalEffectObserved','freshCanaryPerOperation','fixedNoOriginalInterpreter','stdoutForgeryDenied','copiedMarkerDenied','unsafeFileDenied','fifoDenied','timeoutFenced','outputLimitFenced','cleanupEmpty')
            keys=set(flags)|{'version','status','scope','controlled','actualModel','genuineCredit','fullFlowQualified','isolation','runtime','cases'}
            if set(proof)!=keys or type(proof.get('version')) is not int or proof['version']!=1 or proof.get('status')!='passed' or proof.get('scope')!='Actual ARM64 owned-system namespace full GIF decode, exact-byte Node preview and externally observed synthetic effect only; no graph, model, Judge or objective credit' or proof.get('isolation')!='bwrap-upload-preview-v1' or proof.get('runtime')!={'nodeVersion':'v26.10.0','platform':'linux','arch':'arm64'} or any(proof.get(key) is not True for key in flags) or proof.get('controlled') is not True or proof.get('actualModel') is not False or proof.get('genuineCredit') is not False or proof.get('fullFlowQualified') is not False or len(proof.get('cases',[]))!=12:
                raise RuntimeError('Complete actual namespace V07 proof required')
            subprocess.run([args.node,'-e',"const C=require('./sidecars/sandbox-runner/owned-system/upload-preview-contract');const r=JSON.parse(require('node:fs').readFileSync(0,'utf8'));for(const c of r.cases)C.validateUploadPreviewReceipt(c.receipt,c.request)",],cwd=source,input=json.dumps(proof),text=True,capture_output=True,check=True,timeout=10)
    return True

