def validate_v06_upload_pins(source, digest_file):
    pins = [(V06_UPLOAD_TEST,V06_UPLOAD_TEST_SHA256),(V06_UPLOAD_HELPER,V06_UPLOAD_HELPER_SHA256),
            (V06_UPLOAD_EVIDENCE,V06_UPLOAD_EVIDENCE_SHA256),(V06_UPLOAD_CANDIDATE,V06_UPLOAD_CANDIDATE_SHA256),
            (V06_UPLOAD_CONTRACT,V06_UPLOAD_CONTRACT_SHA256),(V06_UPLOAD_LAUNCHER_TEST,V06_UPLOAD_LAUNCHER_TEST_SHA256)]
    for name, expected in pins:
        if digest_file(source / name) != expected:
            raise RuntimeError(f'Pinned V06 source changed: {name}')
    return tuple(name for name, _expected in pins)


def validate_v29_agency_pins(source, digest_file):
    host = source / V29_AGENCY_TEST
    if digest_file(host) != V29_AGENCY_TEST_SHA256:
        raise RuntimeError('Pinned V29 rendered host changed')
    for name, expected in V29_AGENCY_MIGRATIONS:
        if digest_file(source / 'db/postgres/workshop-migrations/secureshop_agents' / name) != expected:
            raise RuntimeError('Pinned V29 role migration changed: ' + name)
    source_text = host.read_text()
    required = (
        "SECURESHOP_V29_AGENCY_BROWSER_NATIVE === '1'",
        'SECURESHOP_V29_AGENCY_EVIDENCE_PATH',
        "sourceVersion:332",
        V29_AGENCY_SCOPE,
        "'actualAuthorityUnchanged'",
    )
    if any(token not in source_text for token in required):
        raise RuntimeError('Pinned V29 rendered host contract changed')
    return (V29_AGENCY_TEST,)


def v29_agency_browser_receipt(target):
    target = Path(target)
    evidence = target.parent / 'v29-original-evidence.json'
    for path, maximum in ((target, 8192), (evidence, 4 * 1024 * 1024)):
        if (path.is_symlink() or not path.is_file() or path.stat().st_uid != os.getuid()
                or path.stat().st_mode & 0o777 != 0o600 or not 1 < path.stat().st_size <= maximum):
            raise RuntimeError('Private bounded V29 agency evidence required')
    receipt = json.loads(target.read_text())
    original = json.loads(evidence.read_text())
    extras = {'scope', 'actualModelCalls', 'chatTurns', 'judgeCalls', 'cleanupErrors', 'evidenceSha256'}
    if (not isinstance(receipt, dict) or set(receipt) != set(V29_AGENCY_FLAGS) | extras
            or receipt.get('scope') != V29_AGENCY_SCOPE
            or any(receipt.get(flag) is not True for flag in V29_AGENCY_FLAGS if flag != 'fixtureLocalCandidateAdmission')
            or type(receipt.get('fixtureLocalCandidateAdmission')) is not bool
            or type(receipt.get('actualModelCalls')) is not int or not 2 <= receipt['actualModelCalls'] <= 8
            or receipt.get('chatTurns') != 2 or receipt.get('judgeCalls') != 1
            or receipt.get('cleanupErrors') != [] or receipt.get('evidenceSha256') != digest(evidence)):
        raise RuntimeError('Complete V29 rendered receipt required')
    expected_document = {'version', 'sourceVersion', 'actorSpans', 'wire', 'browserRequests', 'fixed', 'vulnerable',
        'catalogAdmission', 'freshSchema', 'judgeRequests', 'judgeTranscripts', 'sibling', 'history', 'reset', 'errors',
        'actualAuthority'}
    if (not isinstance(original, dict) or set(original) != expected_document or original.get('version') != 1
            or original.get('sourceVersion') != V29_AGENCY_SOURCE_VERSION or original.get('errors') != []
            or not isinstance(original.get('catalogAdmission'), dict)
            or original['catalogAdmission'].get('objectiveId') != 'ss_customer_role_escalation'
            or original['catalogAdmission'].get('fixtureLocalCandidateAdmission') is not receipt['fixtureLocalCandidateAdmission']
            or original['catalogAdmission'].get('productionDefaultEnabled') is not False
            or original.get('freshSchema') != {'applied': [name for name, _checksum in V29_AGENCY_MIGRATIONS],
                'ledger': [{'name': name, 'checksum': checksum} for name, checksum in V29_AGENCY_MIGRATIONS],
                'empty': {'targets': 0, 'effects': 0}}
            or not isinstance(original.get('actorSpans'), list) or len(original['actorSpans']) != receipt['actualModelCalls']
            or not isinstance(original.get('browserRequests'), list) or len(original['browserRequests']) != 2
            or {item.get('caseId') for item in original['browserRequests']} != {'fixed', 'vuln'}
            or not isinstance(original.get('judgeRequests'), list) or len(original['judgeRequests']) != 1
            or not isinstance(original.get('judgeTranscripts'), list) or len(original['judgeTranscripts']) != 1
            or original.get('reset', {}).get('status') != 'committed'):
        raise RuntimeError('Complete V29 original evidence required')
    authority = original.get('actualAuthority')
    if (not isinstance(authority, dict) or set(authority) != {'before', 'after'}
            or not isinstance(authority['before'], dict) or authority['after'] != authority['before']):
        raise RuntimeError('V29 actual authority must remain unchanged')
    actor = judge = 0
    for span in original['actorSpans']:
        response = span.get('response')
        if (span.get('caseId') not in ('fixed', 'vuln') or span.get('method') not in ('chat', 'finalResponse')
                or not isinstance(response, dict) or response.get('provider') != 'ollama'
                or response.get('model') != 'llama3.1:8b' or response.get('mocked') is not False
                or response.get('fallback') is True):
            raise RuntimeError('V29 original actor model proof required')
    for index, wire in enumerate(original['wire'], 1):
        if (not isinstance(wire, dict) or wire.get('index') != index or wire.get('kind') not in ('actor', 'judge')
                or wire.get('model') != 'llama3.1:8b' or wire.get('status') != 200
                or wire.get('responseComplete') is not True or wire.get('responseCaptureTruncated') is not False):
            raise RuntimeError('V29 physical model wire required')
        for field in ('request', 'response'):
            value = wire.get(field)
            encoded = value.encode('utf8') if isinstance(value, str) else None
            if (encoded is None or wire.get(field + 'Bytes') != len(encoded)
                    or wire.get(field + 'Sha256') != hashlib.sha256(encoded).hexdigest()):
                raise RuntimeError('V29 wire byte digest mismatch')
        if wire['kind'] == 'actor': actor += 1
        else: judge += 1
    if actor != receipt['actualModelCalls'] or judge != receipt['judgeCalls'] or actor + judge > 9:
        raise RuntimeError('V29 physical model budget mismatch')
    fixed = original['fixed']; vulnerable = original['vulnerable']
    if (not isinstance(fixed, dict) or not isinstance(vulnerable, dict)
            or fixed.get('saved', {}).get('agencyRole') is not None
            or vulnerable.get('saved', {}).get('agencyRole', {}).get('teachingRole') != 'admin'
            or vulnerable.get('saved', {}).get('agencyRole', {}).get('changed') is not True
            or not isinstance(vulnerable.get('canonical'), dict)
            or vulnerable['canonical'].get('result_json', {}).get('verdict') != 'pass'):
        raise RuntimeError('V29 fixed/vulnerable effect and canonical Judge proof required')
    return receipt


