def validate_v44_native_result(args, source):
    target = Path(args.v44_native_result or '')
    if (not target.is_absolute() or target.is_symlink() or not target.is_file()
            or target.resolve().is_relative_to(source) or target.stat().st_uid != os.getuid()
            or target.stat().st_mode & 0o777 != 0o600 or target.stat().st_size > 2*1024*1024
            or not re.fullmatch(r'[a-f0-9]{64}',args.v44_native_result_sha256 or '')
            or digest(target) != args.v44_native_result_sha256):
        raise RuntimeError('Private hash-bound V44 native result required')
    result=json.loads(target.read_text())
    if (any(result.get(key) is not True for key in ('passed','sourceUnchanged','dependenciesUnchanged','containerAbsent','childGroupsAbsent','graph','ownedFileEffect'))
            or any(result.get(key) is not False for key in ('sourceCopies','actualModel','browser','judgeOrCredit'))
            or type(result.get('exitCode')) is not int or result['exitCode'] != 0
            or type(result.get('expectedTests')) is not int or result['expectedTests'] != 2
            or result.get('fixture') != 'tests/postgres/secureshopV19FileSummaryNative.integration.test.js'
            or result.get('cleanupErrors') != []):
        raise RuntimeError('Complete clean V44 native qualification required')
    tap=target.parent/'test.stdout.log'
    if (tap.is_symlink() or not tap.is_file() or tap.stat().st_uid != os.getuid()
            or tap.stat().st_mode & 0o777 != 0o600 or tap.stat().st_size > 1024*1024
            or digest(tap) != result.get('stdoutSha256')
            or result.get('sourceHashesAfter') != result.get('sourceHashes')):
        raise RuntimeError('Bound unchanged V44 native source and TAP required')
    native_tap=complete_tap_counts(tap.read_text(),'V44 native admission',[
        '0107/0108/0109 fresh, populated and no-op preserve historical purposes, ledger, operator ACL edits and sibling evidence',
        'default graph persists real PG policy/turn/effect and owned bytes; replay/read cannot duplicate or repair effects'])
    if native_tap['tests'] != 2:raise RuntimeError('Exact two V44 native assertions required')
    for name,expected in V44_NATIVE_PINS.items():
        if result.get('sourceHashes',{}).get(name) != expected or digest(source/name) != expected:
            raise RuntimeError('V44 native executed source incompatible: '+name)
    return result


