def standalone_commerce_receipt(target, admission=None, policy_source_sha256=None):
    target = Path(target)
    if target.is_symlink() or not target.is_file() or target.stat().st_uid != os.getuid() or target.stat().st_mode & 0o777 != 0o600 or target.stat().st_size > 4096:
        raise RuntimeError('Private owned commerce receipt required')
    receipt = json.loads(target.read_text())
    required = set(STANDALONE_COMMERCE_FLAGS) | {
        'scope', 'policySavedOperationRecovery', 'policyRecovery',
        'unavailableProviderAttempts', 'unavailableProviderAccounting', 'actualModelCalls'}
    if (not isinstance(receipt, dict) or set(receipt) != required
            or any(receipt.get(key) is not True for key in STANDALONE_COMMERCE_FLAGS) or receipt['scope'] != STANDALONE_COMMERCE_SCOPE):
        raise RuntimeError('Complete commerce assertion receipt required')
    # Two authenticated Product decisions are the baseline. A18 may remount its
    # rendered Product frame, but each extra unavailable-provider call must be
    # tied to a rendered Product read and the bound Product-assist graph.
    accounting = receipt['unavailableProviderAccounting']
    accounting_keys = {'version', 'baselineAuthenticatedProductAttempts',
                       'productAutomaticRenderedReadRequests', 'productAutomaticAssistAttempts',
                       'productAutomaticAssistSource'}
    if (not isinstance(accounting, dict) or set(accounting) != accounting_keys
            or type(accounting['version']) is not int or accounting['version'] != 1
            or type(accounting['baselineAuthenticatedProductAttempts']) is not int
            or accounting['baselineAuthenticatedProductAttempts'] != 2
            or type(accounting['productAutomaticRenderedReadRequests']) is not int
            or accounting['productAutomaticRenderedReadRequests'] < 0
            or type(accounting['productAutomaticAssistAttempts']) is not int
            or not 0 <= accounting['productAutomaticAssistAttempts'] <= 6
            or accounting['productAutomaticAssistAttempts'] > accounting['productAutomaticRenderedReadRequests']
            or accounting['productAutomaticAssistSource'] != 'secureshopBoundProductAssist'
            or type(receipt['unavailableProviderAttempts']) is not int
            or receipt['unavailableProviderAttempts'] != 2 + accounting['productAutomaticAssistAttempts']
            or not 2 <= receipt['unavailableProviderAttempts'] <= 8
            or type(receipt['actualModelCalls']) is not int or receipt['actualModelCalls'] != 0):
        raise RuntimeError('Bounded Product-assist and actual-model accounting required')
    policy = receipt['policyRecovery']
    if admission is None:
        if receipt['policySavedOperationRecovery'] is not False or policy != {'status':'not-run','reason':'No explicit external renderer admission supplied'}:
            raise RuntimeError('Unadmitted policy qualification claim')
    else:
        keys = {'status','managedSha256','sourceSha256','containerId','imageId','operationId','version','requestSha256','renderCalls','mutationPosts','siblingLaunchId'}
        uuid_pattern = r'[a-f0-9]{8}-[a-f0-9]{4}-[1-5][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}'
        if (receipt['policySavedOperationRecovery'] is not True or not isinstance(policy, dict) or set(policy) != keys
                or policy['status'] != 'passed' or policy['managedSha256'] != admission['value']['managedSha256']
                or policy['sourceSha256'] != policy_source_sha256
                or not all(isinstance(policy[k], str) and re.fullmatch(r'[a-f0-9]{64}', policy[k]) for k in ('managedSha256','sourceSha256','containerId','requestSha256'))
                or not isinstance(policy['imageId'], str) or not re.fullmatch(r'sha256:[a-f0-9]{64}',policy['imageId'])
                or not all(isinstance(policy[k], str) and re.fullmatch(uuid_pattern,policy[k]) for k in ('operationId','siblingLaunchId'))
                or not isinstance(policy['version'], str) or not re.fullmatch(r'[1-9][0-9]{0,18}',policy['version'])
                or any(type(policy[k]) is not int or policy[k] != 1 for k in ('renderCalls','mutationPosts'))):
            raise RuntimeError('Admitted policy recovery proof required')
    return receipt


