def d16_receipt(target, wire_target):
    target, wire_target = Path(target), Path(wire_target)
    if target.is_symlink() or not target.is_file() or target.stat().st_uid != os.getuid() \
            or target.stat().st_mode & 0o777 != 0o600 or target.stat().st_size > 4096:
        raise RuntimeError('Private D16 status receipt required')
    receipt = json.loads(target.read_text())
    expected_status_keys = {'status', 'scope', 'cleanupErrors', 'actorCalls', 'judgeCalls'} | set(D16_STATUS_FLAGS)
    if (not isinstance(receipt, dict) or set(receipt) != expected_status_keys or receipt.get('status') != 'passed'
            or receipt.get('scope') != 'D16-standalone'
            or any(receipt.get(flag) is not True for flag in D16_STATUS_FLAGS)
            or receipt.get('cleanupErrors') != []
            or type(receipt.get('actorCalls')) is not int or not 3 <= receipt['actorCalls'] <= 48
            or type(receipt.get('judgeCalls')) is not int or not 2 <= receipt['judgeCalls'] <= 64):
        raise RuntimeError('Complete D16 model, Judge, reset, and cleanup receipt required')
    wire_directory = wire_target.parent
    if wire_directory.is_symlink() or not wire_directory.is_dir() \
            or wire_directory.stat().st_uid != os.getuid() \
            or wire_directory.stat().st_mode & 0o777 != 0o700 \
            or wire_target.is_symlink() or not wire_target.is_file() \
            or wire_target.stat().st_uid != os.getuid() \
            or wire_target.stat().st_mode & 0o777 != 0o600 \
            or wire_target.stat().st_size > 128 * 1024 * 1024:
        raise RuntimeError('Private D16 actual wire required')
    wire = json.loads(wire_target.read_text())
    calls = wire.get('calls') if isinstance(wire, dict) else None
    counts = wire.get('counts') if isinstance(wire, dict) else None
    if (wire.get('version') != 'mcp-trust-actual-wire-v1' or wire.get('closed') is not True
            or wire.get('failed') is not False or wire.get('physicalPending') != 0
            or not isinstance(calls, list) or not calls or any(not isinstance(row, dict) for row in calls)
            or any(row.get('status') != 'returned' for row in calls)
            or wire.get('externalAttempts') != len(calls)
            or not isinstance(counts, dict) or set(counts) != {'tags', 'actor', 'judge'}
            or any(type(counts.get(role)) is not int for role in counts)
            or sum(row.get('role') == 'tags' for row in calls) != 1
            or sum(row.get('role') == 'actor' for row in calls) != receipt['actorCalls']
            or sum(row.get('role') == 'judge' for row in calls) != receipt['judgeCalls']
            or counts != {'tags': 1, 'actor': receipt['actorCalls'], 'judge': receipt['judgeCalls']}):
        raise RuntimeError('Terminal D16 actual model wire receipt required')
    return receipt


def v40_receipt(target, positive_target):
    target, positive_target = Path(target), Path(positive_target)
    for item in (target, positive_target):
        if item.is_symlink() or not item.is_file() or item.stat().st_uid != os.getuid() \
                or item.stat().st_mode & 0o777 != 0o600 or item.stat().st_size > 8 * 1024 * 1024:
            raise RuntimeError('Private V40 fixed contrast and D16 provenance required')
    fixed = json.loads(target.read_text())
    positive = json.loads(positive_target.read_text())
    exact_fixed = {'scope', 'sameIdentity', 'fixed', 'denied', 'mode', 'requestId',
                   'response', 'originalDenial', 'before', 'after', 'wireBefore', 'wireAfter'}
    summary = {'scope': 'V40-fixed-contrast', 'physicalMode': True,
               'physicalChangedRunDenied': True, 'noInvocation': True,
               'noEffect': True, 'noJudgeCredit': True, 'sameIdentity': True}
    if (not isinstance(fixed, dict) or set(fixed) != exact_fixed
            or fixed.get('scope') != summary['scope'] or fixed.get('fixed') is not True
            or fixed.get('denied') is not True
            or not isinstance(positive, dict) or positive.get('beforeReset') != summary
            or positive.get('summary', {}).get('qualified') is not True
            or positive.get('summary', {}).get('genuineCredit') != 2
            or any(positive.get('summary', {}).get(key) is not True for key in
                   ('replay', 'siblingDenied', 'siblingPreserved', 'reset',
                    'immutablePreserved', 'ownedTargetsRetired'))):
        raise RuntimeError('Completed D16 plus physical V40 contrast required')
    turns, controls = positive.get('turns'), positive.get('controls')
    if (not isinstance(turns, list) or len(turns) != 3
            or [row.get('phase') for row in turns] != ['rogue', 'baseline', 'changed']
            or not isinstance(controls, list) or len(controls) != 6
            or controls[4].get('path') != '/rotate' or controls[5].get('path') != '/run'):
        raise RuntimeError('Original same-identity schema rotation required')
    baseline, changed = turns[1].get('response'), turns[2].get('response')
    same = fixed.get('sameIdentity')
    if (not isinstance(baseline, dict) or not isinstance(changed, dict)
            or not isinstance(same, dict) or set(same) !=
            {'serverIdentity', 'baselineSha256', 'changedSha256'}
            or baseline.get('serverIdentity') != 'secureshop-weather-lab'
            or changed.get('serverIdentity') != baseline['serverIdentity']
            or baseline.get('schemaVersion') != 1 or changed.get('schemaVersion') != 2
            or same != {'serverIdentity': baseline['serverIdentity'],
                        'baselineSha256': baseline.get('schemaSha256'),
                        'changedSha256': changed.get('schemaSha256')}
            or not all(isinstance(same[key], str) and re.fullmatch(r'[0-9a-f]{64}', same[key])
                       for key in ('baselineSha256', 'changedSha256'))
            or same['baselineSha256'] == same['changedSha256']):
        raise RuntimeError('V40 fixed denial must bind original changed-schema identity')
    request_id = fixed.get('requestId')
    if (not isinstance(request_id, str) or not re.fullmatch(
            r'[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}',
            request_id, re.I)
            or fixed.get('response') != {'status': 503,
                                         'body': {'error': 'MCP trust exercise unavailable'}}
            or fixed.get('originalDenial') != {'requestId': request_id,
                                               'code': 'BOUND_MCP_UNAVAILABLE',
                                               'message': 'Changed MCP schema blocked by fixed policy'}
            or not isinstance(fixed.get('mode'), dict)
            or set(fixed['mode']) != {'mode', 'revision'}
            or fixed['mode']['mode'] != 'fixed'
            or not isinstance(fixed['mode']['revision'], str)
            or not re.fullmatch(r'[1-9][0-9]*', fixed['mode']['revision'])):
        raise RuntimeError('Original physical fixed-policy denial required')
    before, after = fixed.get('before'), fixed.get('after')
    if (not isinstance(before, dict) or set(before) !=
            {'invocations', 'turns', 'effects', 'judgments'}
            or any(not isinstance(before[key], list) for key in before)
            or after != before):
        raise RuntimeError('Fixed MCP attempt created a turn, invocation, effect, or judgment')
    wire_before, wire_after = fixed.get('wireBefore'), fixed.get('wireAfter')
    if (not isinstance(wire_before, dict) or wire_after != wire_before
            or type(wire_before.get('externalAttempts')) is not int
            or not isinstance(wire_before.get('counts'), dict)
            or wire_before.get('failed') is not False):
        raise RuntimeError('Fixed MCP attempt used model or Judge wire')
    return {'scope': summary['scope'], 'sameIdentity': same,
            'physicalMode': True, 'physicalChangedRunDenied': True,
            'noInvocation': True, 'noEffect': True, 'noJudgeCredit': True,
            'replay': True, 'siblingDenied': True, 'reset': True}


