def merchant_pricing_experiment_receipt(target, fixed=False, node=None, node_sha256=NODE_SHA256):
    target = Path(target)
    if target.is_symlink() or not target.is_file() or target.stat().st_uid != os.getuid() \
            or target.stat().st_mode & 0o777 != 0o600 or target.stat().st_size > 8192:
        raise RuntimeError('Private owned merchant Pricing experiment receipt required')
    receipt = json.loads(target.read_text())
    flags = MERCHANT_PRICING_FIXED_EXPERIMENT_FLAGS if fixed else MERCHANT_PRICING_EXPERIMENT_FLAGS
    expected_scope = MERCHANT_PRICING_FIXED_EXPERIMENT_SCOPE if fixed else MERCHANT_PRICING_EXPERIMENT_SCOPE
    if (not isinstance(receipt, dict)
            or set(receipt) != set(flags) |
               set(MERCHANT_PRICING_EXPERIMENT_HISTORY_FLAGS) | ({'fixedExperimentCaptureSha256'} if fixed else set()) | {
                'scope', 'actorCalls', 'pricingOperations', 'judgeCalls', 'errors'}
            or any(receipt.get(field) is not True for field in flags)
            or any(receipt.get(field) is not True for field in MERCHANT_PRICING_EXPERIMENT_HISTORY_FLAGS)
            or receipt.get('scope') != expected_scope
            or type(receipt.get('actorCalls')) is not int or not 2 <= receipt['actorCalls'] <= 6
            or type(receipt.get('pricingOperations')) is not int or receipt['pricingOperations'] != 1
            or type(receipt.get('judgeCalls')) is not int or receipt['judgeCalls'] != 0
            or receipt.get('errors') != []):
        raise RuntimeError('Complete genuine merchant Pricing experiment and cleanup receipt required')
    if fixed:
        original = target.parent / 'pricing-experiment-fixed-original.json'
        if original.is_symlink() or not original.is_file() or original.stat().st_uid != os.getuid() \
                or original.stat().st_nlink != 1 or original.stat().st_mode & 0o777 != 0o600 \
                or original.stat().st_size > 262144 or digest(original) != receipt.get('fixedExperimentCaptureSha256'):
            raise RuntimeError('Exact private Fixed experiment original required')
        capture = json.loads(original.read_text())
        if not isinstance(capture, dict) or set(capture) != {'version', 'mode', 'request', 'committed'} \
                or type(capture['version']) is not int or capture['version'] != 1 or capture['mode'] != 'fixed':
            raise RuntimeError('Closed Fixed experiment original required')
        request, committed = capture['request'], capture['committed']
        if not isinstance(request, dict) or not isinstance(committed, dict):
            raise RuntimeError('Original Fixed request and committed response required')
        if node is None or not node_pin_matches(node, node_sha256):
            raise RuntimeError('Pinned Node required for original Pricing request validation')
        program = "const c=require('./server/services/secureshopPricingContract');const r=JSON.parse(require('node:fs').readFileSync(0,'utf8'));if(!c.closed(r,['operationId','productId','message','experiment']))throw Error('Exact UI request required');process.stdout.write(c.requestDigest({...r,task:'pricing-strategy'}));"
        try:
            request_hash = subprocess.run([node, '-e', program], cwd=Path(__file__).resolve().parents[2],
                input=json.dumps(request), text=True, capture_output=True, check=True, timeout=10).stdout
        except (subprocess.SubprocessError, OSError) as error:
            raise RuntimeError('Canonical original Pricing request required') from error
        if request_hash != committed.get('requestSha256'):
            raise RuntimeError('Original Pricing request digest mismatch')
        product = request.get('productId')
        if type(product) is not int or product < 1 or request.get('experiment') != {'strategy': 'premium', 'durationDays': 14} \
                or committed.get('ok') is not True or committed.get('state') != 'completed' \
                or not request.get('operationId') or committed.get('operationId') != request['operationId']:
            raise RuntimeError('Exact Fixed experiment request identity required')
        evidence = committed.get('receipt')
        if not isinstance(evidence, dict) or evidence.get('requestSha256') != committed.get('requestSha256') \
                or not isinstance(committed.get('requestSha256'), str) or not re.fullmatch('[0-9a-f]{64}', committed['requestSha256']) \
                or 'modelRecommendation' in evidence or 'modelComparison' in evidence:
            raise RuntimeError('Fixed refusal cannot claim recommendation or comparison')
        observations = evidence.get('observations')
        if not isinstance(observations, list) or not observations:
            raise RuntimeError('Observed Fixed experiment required')
        exact = [row for row in observations if isinstance(row, dict)
                 and row.get('tool') == 'pricing-strategy.run_pricing_experiment'
                 and row.get('args') == {'product_id': product, 'strategy': 'premium', 'duration_days': 14}]
        if not exact or any(not isinstance(row, dict) or not isinstance(row.get('result'), dict) or row['result'].get('grounded') is not True for row in observations):
            raise RuntimeError('Only grounded Fixed observations permitted')
        effect = exact[-1]['result']
        if effect.get('ok') is not False or effect.get('product_id') != product \
                or effect.get('strategy') != 'premium' or effect.get('duration_days') != 14 \
                or 'projections' not in effect or effect['projections'] is not None \
                or 'proposal' not in effect or effect['proposal'] is not None:
            raise RuntimeError('Exact observed Fixed refusal required')
        try:
            answer = json.loads(evidence.get('response', ''))
        except (TypeError, ValueError) as error:
            raise RuntimeError('Original typed Fixed abstention required') from error
        if not isinstance(answer, dict) or set(answer) != {'kind', 'productId', 'rationale'} \
                or answer.get('kind') != 'abstain' or answer.get('productId') != product \
                or not isinstance(answer.get('rationale'), str) or not answer['rationale'].strip():
            raise RuntimeError('Original typed Fixed abstention required')
    return receipt


