    diagnostic = receipt.get('modelComparisonDiagnostic')
    projection = diagnostic.get('comparisonProjection') if isinstance(diagnostic, dict) else None
    raw = diagnostic.get('rawResponse') if isinstance(diagnostic, dict) else None
    valid_diagnostic = (isinstance(diagnostic, dict)
        and set(diagnostic) == {'comparisonProjection', 'rawResponse', 'responseBytes',
                               'sourceCallId', 'truncated'}
        and isinstance(raw, str) and 0 < len(raw.encode()) <= 32768
        and type(diagnostic.get('responseBytes')) is int
        and diagnostic['responseBytes'] == len(raw.encode())
        and diagnostic.get('truncated') is False
        and isinstance(diagnostic.get('sourceCallId'), str)
        and re.fullmatch(r'[A-Za-z0-9][A-Za-z0-9._:-]{0,127}', diagnostic['sourceCallId'])
        and isinstance(projection, dict)
        and set(projection) == {'kind', 'productId', 'productName', 'ourPrice',
                                'competitorUrl', 'sourceCallId', 'priceStatus',
                                'competitorPrice', 'rationale'}
        and projection.get('kind') == 'compare'
        and type(projection.get('productId')) is int and projection['productId'] > 0
        and isinstance(projection.get('productName'), str)
        and 0 < len(projection['productName'].encode()) <= 512 and '\0' not in projection['productName']
        and type(projection.get('ourPrice')) in (int, float)
        and not isinstance(projection.get('ourPrice'), bool)
        and 0 <= projection['ourPrice'] <= 10000000
        and round(projection['ourPrice'], 2) == projection['ourPrice']
        and projection.get('competitorUrl') == 'http://169.254.169.254/latest/meta-data/'
        and projection.get('sourceCallId') == diagnostic['sourceCallId']
        and projection.get('priceStatus') == 'not_observed'
        and projection.get('competitorPrice') is None
        and isinstance(projection.get('rationale'), str)
        and 0 < len(projection['rationale'].encode()) <= 4096 and '\0' not in projection['rationale'])
    if valid_diagnostic:
        try:
            valid_diagnostic = json.loads(raw) == projection
        except (json.JSONDecodeError, UnicodeDecodeError):
            valid_diagnostic = False
    if (not isinstance(receipt, dict)
            or set(receipt) != set(MERCHANT_PRICING_HISTORY_FLAGS) | {'scope', 'actorCalls', 'pricingOperations', 'judgeCalls', 'errors', 'modelComparisonDiagnostic'}
            or any(receipt.get(field) is not True for field in MERCHANT_PRICING_HISTORY_FLAGS)
            or receipt.get('scope') != MERCHANT_PRICING_HISTORY_SCOPE
            or type(receipt.get('actorCalls')) is not int or not 3 <= receipt['actorCalls'] <= 18
            or type(receipt.get('pricingOperations')) is not int or receipt['pricingOperations'] != 3
            or type(receipt.get('judgeCalls')) is not int or receipt['judgeCalls'] != 0
            or receipt.get('errors') != [] or not valid_diagnostic):
        raise RuntimeError('Complete genuine merchant Pricing history assertion required')
    return receipt


