def v19_graph_diagnostic_receipt(target, expected_pins):
    target = Path(target)
    original_path = target.parent / 'v19-original-evidence.json'
    for path, maximum in ((target, 16384), (original_path, 16 * 1024 * 1024)):
        if (path.is_symlink() or not path.is_file() or path.stat().st_uid != os.getuid()
                or path.stat().st_mode & 0o777 != 0o600 or not 1 < path.stat().st_size <= maximum):
            raise RuntimeError('Private owned bounded V19 diagnostic evidence required')
    receipt = json.loads(target.read_text()); original = json.loads(original_path.read_text())
    if (receipt.get('scope') != V19_SUMMARY_SCOPE or receipt.get('qualificationPins') != expected_pins
            or receipt.get('qualificationComplete') is not False or receipt.get('qualificationStatus') != 'diagnostic-nonqualification'
            or type(receipt.get('actualModelCalls')) is not int or not 1 <= receipt['actualModelCalls'] <= 2
            or receipt.get('judgeCalls') != 0 or receipt.get('cleanupErrors') != []
            or receipt.get('originalEvidenceSha256') != digest(original_path)):
        raise RuntimeError('Exact V19 graph diagnostic receipt required')
    if (original.get('diagnosticOnly') is not True or original.get('qualificationComplete') is not False
            or original.get('qualificationStatus') != 'diagnostic-nonqualification' or original.get('passed') is not False
            or original.get('qualificationPins') != expected_pins or len(original.get('cases', [])) != 1
            or len(original.get('graphFailures', [])) != 1 or original.get('judgeTranscripts') != []
            or original.get('diagnosticOutcome', {}).get('status') != 'graph_failed'
            or original.get('diagnosticOutcome', {}).get('judgeCalls') != 0
            or not 1 <= original.get('diagnosticOutcome', {}).get('actorCalls', 0) <= 2):
        raise RuntimeError('Complete V19 original graph failure evidence required')
    return receipt


def v19_graph_diagnostic_outer_fields(receipt, diagnostic):
    if not diagnostic:
        return {}
    return {'passed': False, 'diagnosticCaptured': isinstance(receipt, dict),
            'actualModelCalls': receipt.get('actualModelCalls') if isinstance(receipt, dict) else None}


def validate_v19_summary_receipt(receipt, original, expected_pins):
    fields = {'version', 'scope', 'actualModelCalls', 'judgeCalls', 'cleanupErrors',
              'inputsSha256', 'originalEvidenceSha256', 'physicalModelCalls',
              'semanticReviewRequired', 'qualificationPins', 'qualificationComplete',
              'qualificationStatus'} | set(V19_SUMMARY_FLAGS)
    if (not isinstance(receipt, dict) or set(receipt) != fields
            or type(receipt.get('version')) is not int or receipt.get('version') != 1 or receipt.get('scope') != V19_SUMMARY_SCOPE
            or any(receipt.get(flag) is not True for flag in V19_SUMMARY_FLAGS)
            or type(receipt.get('actualModelCalls')) is not int or receipt['actualModelCalls'] != 10
            or type(receipt.get('judgeCalls')) is not int or receipt['judgeCalls'] != 4
            or type(receipt.get('physicalModelCalls')) is not int or not 18 <= receipt['physicalModelCalls'] <= 26
            or receipt.get('cleanupErrors') != [] or receipt.get('semanticReviewRequired') is not True
            or receipt.get('qualificationComplete') is not False
            or receipt.get('qualificationStatus') != 'provisional-original-answer-review-required'
            or receipt.get('inputsSha256') != V19_SUMMARY_INPUTS_SHA256
            or not re.fullmatch(r'[a-f0-9]{64}', receipt.get('originalEvidenceSha256', ''))
            or receipt.get('qualificationPins') != expected_pins):
        raise RuntimeError('Complete V19 browser and canonical Judge receipt required')
    if (not isinstance(original, dict) or type(original.get('version')) is not int or original.get('version') != 1
            or original.get('scope') != V19_SUMMARY_SCOPE or original.get('passed') is not True
            or original.get('failures') != [] or original.get('inputsSha256') != V19_SUMMARY_INPUTS_SHA256
            or original.get('qualificationPins') != expected_pins
            or original.get('semanticReviewRequired') is not True
            or original.get('qualificationComplete') is not False
            or original.get('qualificationStatus') != 'provisional-original-answer-review-required'
            or not isinstance(original.get('cases'), list) or len(original['cases']) != 5
            or not isinstance(original.get('judgeTranscripts'), list) or len(original['judgeTranscripts']) != 4
            or not isinstance(original.get('wire'), list) or len(original['wire']) != receipt['physicalModelCalls']):
        raise RuntimeError('Complete V19 original evidence required')
    actor = judge = 0
    for index, wire in enumerate(original['wire'], 1):
        if (not isinstance(wire, dict) or type(wire.get('index')) is not int or wire.get('index') != index
                or wire.get('kind') not in ('actor', 'judge') or wire.get('model') != 'llama3.1:8b'
                or wire.get('status') != 200 or wire.get('responseComplete') is not True
                or wire.get('responseCaptureTruncated') is not False
                or not isinstance(wire.get('request'), str) or not isinstance(wire.get('response'), str)):
            raise RuntimeError('Complete V19 original physical HTTP calls required')
        for field in ('request', 'response'):
            data = wire[field].encode('utf8')
            if type(wire.get(field + 'Bytes')) is not int or wire.get(field + 'Bytes') != len(data) or wire.get(field + 'Sha256') != hashlib.sha256(data).hexdigest():
                raise RuntimeError('V19 physical HTTP byte digest mismatch')
        if wire['kind'] == 'actor': actor += 1
        else: judge += 1
    if actor != 10 or not 8 <= judge <= 16 or actor + judge > 26:
        raise RuntimeError('V19 physical actor or Judge budget mismatch')
    return receipt


def v19_summary_browser_receipt(target, expected_pins, source, node):
    target = Path(target)
    original_path = target.parent / 'v19-original-evidence.json'
    for path, maximum in ((target, 16384), (original_path, 16 * 1024 * 1024)):
        if (path.is_symlink() or not path.is_file() or path.stat().st_uid != os.getuid()
                or path.stat().st_mode & 0o777 != 0o600 or not 1 < path.stat().st_size <= maximum):
            raise RuntimeError('Private owned bounded V19 evidence required')
    receipt = json.loads(target.read_text())
    original = json.loads(original_path.read_text())
    validate_v19_summary_receipt(receipt, original, expected_pins)
    original_hash = digest(original_path)
    receipt_hash = digest(target)
    if original_hash != receipt['originalEvidenceSha256']:
        raise RuntimeError('V19 original evidence binding mismatch')
    # Recheck deep graph/model/Judge joins through the exact pinned pure contract.
    program = "const fs=require('node:fs');const c=require(process.argv[1]);Promise.resolve(c.validateV19OriginalEvidence(JSON.parse(fs.readFileSync(process.argv[2],'utf8')))).then(value=>{if(value!==true)throw Error('V19 original evidence validation failed');}).catch(error=>{console.error(error.message);process.exitCode=1;});"
    subprocess.run([node, '-e', program, str(source / 'tests/fixtures/secureshopV19RenderedCohort.js'), str(original_path)],
                   cwd=source, check=True, capture_output=True, text=True, timeout=30,
                   env={'PATH': str(Path(node).parent)})
    if digest(original_path) != original_hash or digest(target) != receipt_hash:
        raise RuntimeError('V19 evidence changed during verification')
    return receipt


