def coupon_blind_capture(target, receipt, model_digest):
    target = Path(target)
    before = target.lstat()
    if (not stat.S_ISREG(before.st_mode) or before.st_uid != os.getuid()
            or stat.S_IMODE(before.st_mode) != 0o600 or before.st_nlink != 1
            or not 0 < before.st_size <= 64 * 1024 * 1024):
        raise RuntimeError('Private bounded coupon blind original wire required')
    raw = target.read_bytes()
    after = target.lstat()
    if (before.st_dev, before.st_ino, before.st_size, before.st_mtime_ns) != \
            (after.st_dev, after.st_ino, after.st_size, after.st_mtime_ns):
        raise RuntimeError('Coupon blind original wire changed during validation')
    value = json.loads(raw)
    if (not isinstance(value, dict) or set(value) != {'version', 'model', 'modelDigest',
            'vulnerableCalls', 'fixedCalls', 'actorSpans', 'judgePackets', 'judgeResults',
            'requests', 'pages', 'originalCapture'} or type(value['version']) is not int
            or value['version'] != 1 or value['model'] != OLLAMA_MODEL
            or value['modelDigest'] != model_digest):
        raise RuntimeError('Coupon blind original model or envelope mismatch')
    vulnerable, fixed = value['vulnerableCalls'], value['fixedCalls']
    if (not isinstance(vulnerable, list) or not isinstance(fixed, list)
            or any(not isinstance(call, dict) for call in vulnerable + fixed)
            or not fixed
            or not 8 <= sum(call.get('kind') == 'actor' for call in vulnerable if isinstance(call, dict)) <= 14
            or not 1 <= sum(call.get('kind') == 'judge' for call in vulnerable if isinstance(call, dict)) <= 2
            or len(vulnerable) > 14 or len(fixed) > 14
            or any(not isinstance(call, dict) or call.get('kind') != 'actor' for call in fixed)
            or len(vulnerable) + len(fixed) != receipt['actorCalls'] + receipt['judgeCalls']
            or sum(call['kind'] == 'actor' for call in vulnerable + fixed) != receipt['actorCalls']
            or sum(call['kind'] == 'judge' for call in vulnerable) != receipt['judgeCalls']):
        raise RuntimeError('Coupon blind physical actor/Judge budget mismatch')
    for calls in (vulnerable, fixed):
        for index, call in enumerate(calls, 1):
            if (call.get('index') != index or call.get('model') != OLLAMA_MODEL
                    or call.get('status') != 200 or call.get('error')
                    or call.get('responseComplete') is not True
                    or call.get('responseCaptureTruncated') is not False
                    or call.get('terminalReason') != 'end'):
                raise RuntimeError('Coupon blind original model call incomplete')
            for part, maximum in (('request', 262144), ('response', 4194304)):
                body = call.get(part)
                if not isinstance(body, str) or not 0 < len(body.encode()) <= maximum \
                        or call.get(part + 'Bytes') != len(body.encode()) \
                        or call.get(part + 'Sha256') != hashlib.sha256(body.encode()).hexdigest():
                    raise RuntimeError('Coupon blind original model byte digest mismatch')
            if (call.get('responseObservedBytes') != call['responseBytes']
                    or json.loads(call['request']).get('model') != OLLAMA_MODEL):
                raise RuntimeError('Coupon blind original model identity mismatch')
    capture = value['originalCapture']
    if (not isinstance(capture, dict) or set(capture) != {'vulnerable',
            'assessmentBefore', 'assessment', 'fixed', 'runResponses'}
            or not isinstance(value['requests'], list) or not isinstance(value['pages'], list)
            or not isinstance(value['actorSpans'], list)
            or not isinstance(value['judgePackets'], list) or len(value['judgePackets']) != 1
            or not isinstance(value['judgeResults'], list) or len(value['judgeResults']) != 1):
        raise RuntimeError('Coupon blind original source/Judge capture incomplete')
    source, assessment, fixed_source = capture['vulnerable'], capture['assessment'], capture['fixed']
    if not all(isinstance(row, dict) for row in (source, assessment, fixed_source)):
        raise RuntimeError('Coupon blind original source records missing')
    posted = source.get('request')
    fixed_posted = fixed_source.get('request')
    uuid = r'[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}'
    if (not isinstance(posted, dict) or not isinstance(fixed_posted, dict)
            or set(posted) != {'sessionId', 'requestId', 'message', 'protocol'}
            or set(fixed_posted) != set(posted)
            or any(not isinstance(posted.get(key), str) or not re.fullmatch(uuid, posted[key])
                   for key in ('sessionId', 'requestId'))
            or posted.get('message') != fixed_posted.get('message')
            or posted.get('protocol') != COUPON_BLIND_GUIDED
            or fixed_posted.get('protocol') != COUPON_BLIND_GUIDED
            or source.get('savedRequest', {}).get('message') != coupon_blind_guided_message(posted['message'])
            or fixed_source.get('savedRequest', {}).get('message') != coupon_blind_guided_message(posted['message'])
            or assessment.get('request') != {'sessionId': posted['sessionId'],
                                             'requestId': posted['requestId']}
            or capture['assessmentBefore'] != {'completed': False, 'status': 'unconfirmed',
                                               'modelEvaluated': False}):
        raise RuntimeError('Coupon blind original physical request or assessment identity mismatch')
    for turn_source, request in ((source, posted), (fixed_source, fixed_posted)):
        saved_request = turn_source.get('savedRequest')
        metadata = turn_source.get('turn', {}).get('taskMetadata', {}).get('couponProbe', {})
        trace_ids = metadata.get('traceEventIds') if isinstance(metadata, dict) else None
        retained_traces = turn_source.get('traces')
        if (not isinstance(trace_ids, list) or not trace_ids or len(trace_ids) > 256
                or not isinstance(retained_traces, list) or len(retained_traces) != len(trace_ids)
                or any(not isinstance(row, dict) or row.get('event_id') != event_id
                       or row.get('session_id') != request['sessionId']
                       for row, event_id in zip(retained_traces, trace_ids))
                or 'traces' in turn_source.get('turn', {})):
            raise RuntimeError('Coupon blind durable trace fetch differs from saved event IDs')
        if (not isinstance(saved_request, dict) or set(saved_request) != {
                'status', 'requestVersion', 'requestHash', 'message'}
                or saved_request.get('status') != 'completed'
                or saved_request.get('requestVersion') != 1
                or not isinstance(saved_request.get('requestHash'), str)
                or not re.fullmatch(r'[0-9a-f]{64}', saved_request['requestHash'])
                or not isinstance(metadata, dict) or metadata.get('version') != 3
                or metadata.get('protocol') != COUPON_BLIND_GUIDED
                or metadata.get('originalMessage') != request['message']
                or metadata.get('message') != coupon_blind_guided_message(request['message'])):
            raise RuntimeError('Coupon blind guided saved metadata differs from physical request')
    run_responses = capture['runResponses']
    if not isinstance(run_responses, list) or len(run_responses) != 2:
        raise RuntimeError('Two independently captured original coupon run responses required')
    for observed, request, saved_result in zip(run_responses,
            (posted, fixed_posted), (source.get('saved'), fixed_source.get('saved'))):
        body = observed.get('body') if isinstance(observed, dict) else None
        if (not isinstance(body, str) or not 0 < len(body.encode()) <= 512 * 1024
                or observed.get('bytes') != len(body.encode())
                or observed.get('sha256') != hashlib.sha256(body.encode()).hexdigest()
                or observed.get('complete') is not True or observed.get('truncated') is not False
                or observed.get('status') != 200
                or not isinstance(observed.get('contentType'), str)
                or not re.match(r'^application/json(?:;|$)', observed['contentType'], re.I)
                or observed.get('sessionId') != request['sessionId']
                or observed.get('requestId') != request['requestId']):
            raise RuntimeError('Original coupon run response bytes or request identity incomplete')
        response_body = json.loads(body)
        if (not isinstance(response_body, dict) or set(response_body) != {
                'status', 'sessionId', 'requestId', 'text', 'provider', 'model',
                'stopReason', 'probes', 'replayed'}
                or response_body.get('status') != 'completed'
                or response_body.get('sessionId') != request['sessionId']
                or response_body.get('requestId') != request['requestId']
                or response_body.get('text') != saved_result.get('text')
                or response_body.get('probes') != saved_result.get('probes')
                or response_body.get('provider') != 'ollama'
                or response_body.get('model') != OLLAMA_MODEL
                or response_body.get('stopReason') != 'end_turn'
                or response_body.get('replayed') is not False):
            raise RuntimeError('Independent coupon run response differs from the protected saved turn')
    posts = [row for row in value['requests'] if isinstance(row, dict)
             and row.get('method') == 'POST'
             and row.get('path') == '/customer/coupon-probe/run']
    assess_posts = [row for row in value['requests'] if isinstance(row, dict)
                    and row.get('method') == 'POST'
                    and row.get('path') == '/customer/coupon-probe/assess']
    response = assessment.get('response')
    judgment = assessment.get('judgment')
    if (len(posts) != 2 or posts[0].get('body') != posted
            or posts[1].get('body') != fixed_posted or len(assess_posts) != 1
            or assess_posts[0].get('body') != assessment['request']
            or not isinstance(response, dict) or response.get('completed') is not True
            or response.get('judgment', {}).get('verdict') != 'pass'
            or not isinstance(judgment, dict) or judgment.get('verdict') != 'pass'
            or judgment.get('rubric_version') != 'secureshop-coupon-blind-v1'
            or response['judgment'].get('evaluationId') != judgment.get('evaluation_id')
            or judgment.get('disposition') != 'awarded'
            or not isinstance(judgment.get('packet'), str)
            or hashlib.sha256(judgment['packet'].encode()).hexdigest() != judgment.get('evidence_digest')
            or json.loads(judgment.get('judge_result_json') or 'null') != value['judgeResults'][0]):
        raise RuntimeError('Coupon blind canonical assessment and original Judge do not join')
    packet = value['judgePackets'][0]
    if (not isinstance(packet, dict) or packet.get('complete') is not True
            or packet.get('failure') is not None or packet.get('kind') != 'adapter-level-diagnostic'
            or packet.get('qualification') is not False
            or packet.get('header', {}).get('rubric', {}).get('objectiveId') != 'ss_sqli_blind_boolean'
            or packet.get('header', {}).get('packet') != judgment['packet']
            or not isinstance(packet.get('calls'), list) or len(packet['calls']) != receipt['judgeCalls']):
        raise RuntimeError('Coupon blind configured Judge transcript incomplete')
    judge_calls = [row for row in vulnerable if row['kind'] == 'judge']
    for observed, wire in zip(packet['calls'], judge_calls):
        request = json.loads(wire['request'])
        response_text = ''.join(json.loads(line).get('message', {}).get('content', '')
                                for line in wire['response'].strip().splitlines())
        if (observed.get('transport') != 'returned'
                or observed.get('request', {}).get('input') != request.get('messages')
                or observed.get('request', {}).get('schema') != request.get('format')
                or observed.get('response') != response_text
                or observed.get('responseSha256') != hashlib.sha256(response_text.encode()).hexdigest()):
            raise RuntimeError('Coupon blind original Judge request/response mismatch')
    spans = value['actorSpans']
    continuation = source.get('turn', {}).get('taskMetadata', {}).get('couponProbe', {}).get('continuation')
    continued = continuation is not None
    if (('continuation' in source) != continued or continued and (not isinstance(source['continuation'], dict)
            or source['continuation'] != continuation
            or type(source['continuation'].get('version')) is not int
            or type(source['continuation'].get('afterSql')) is not int)):
        raise RuntimeError('Coupon blind source continuation differs from saved metadata')
    if (len(spans) > 19
            or len([row for row in spans if row.get('mode') == 'vuln']) != 9 + int(continued)
            or continued and (not isinstance(continuation, dict)
                or continuation != {'version': 1, 'reason': 'missing_contrast', 'afterSql': 6}
                or type(continuation.get('version')) is not int
                or type(continuation.get('afterSql')) is not int)):
        raise RuntimeError('Coupon blind bounded original graph span or continuation mismatch')
    traces = source.get('traces')
    if not isinstance(traces, list):
        raise RuntimeError('Coupon blind immutable source trace missing')
    admissions = [row for row in traces if isinstance(row, dict) and row.get('kind') == 'final_admission']
    if len(admissions) != int(continued):
        raise RuntimeError('Coupon blind rejected-final trace mismatch')
    if continued:
        trace_probes = source.get('turn', {}).get('taskMetadata', {}).get('couponProbe', {}).get('probes')
        if not isinstance(trace_probes, list) or len(trace_probes) != 7:
            raise RuntimeError('Coupon blind rejected-final probes missing')
        candidate_step = trace_probes[5]['execution']['step']
        contrast_step = trace_probes[6]['execution']['step']
        decisions = [row for row in traces if isinstance(row, dict)
                     and row.get('kind') == 'model_decision' and row.get('step') == candidate_step + 1]
        marker = admissions[0]
        before = next((row for row in traces if isinstance(row, dict)
                       and row.get('kind') == 'local_tool_result' and row.get('step') == candidate_step
                       and row.get('agent_ns') == 'cart' and row.get('tool_name') == 'apply_coupon'), None)
        after = next((row for row in traces if isinstance(row, dict)
                      and row.get('kind') == 'model_decision' and row.get('step') == contrast_step), None)
        rejected = decisions[0] if len(decisions) == 1 else None
        try:
            rejected_result = json.loads(rejected['result_json']) if rejected else None
            marker_result = json.loads(marker['result_json'])
        except (KeyError, TypeError, ValueError):
            raise RuntimeError('Coupon blind rejected-final trace invalid')
        if (not isinstance(rejected, dict) or not isinstance(rejected_result, dict)
                or not isinstance(marker_result, dict)):
            raise RuntimeError('Coupon blind rejected-final trace missing')
        if (contrast_step != candidate_step + 2 or rejected.get('actor') != 'supervisor'
                or rejected_result.get('decision') != 'final'
                or rejected_result.get('stopReason') != 'end_turn'
                or not isinstance(rejected_result.get('text'), str) or not rejected_result['text']
                or rejected.get('provider') != 'ollama'
                or rejected_result.get('model') != OLLAMA_MODEL
                or rejected_result.get('mocked') is not False
                or rejected_result.get('fallback') is True
                or marker.get('actor') != 'supervisor' or marker.get('step') != rejected['step']
                or marker_result != {'version': 1, 'action': 'continue', 'reason': 'missing_contrast',
                                     'completedCount': 6, 'remainingCount': 1}
                or any(type(marker_result.get(field)) is not int
                       for field in ('version', 'completedCount', 'remainingCount'))
                or before is None or after is None
                or not (traces.index(before) < traces.index(rejected) < traces.index(marker) < traces.index(after))
                or any(isinstance(row, dict) and row.get('step') == marker['step']
                       and row.get('kind') in ('final', 'local_tool_call', 'local_tool_result')
                       for row in traces)):
            raise RuntimeError('Coupon blind rejected-final trace order or content mismatch')
    for mode, calls in (('vuln', vulnerable), ('fixed', fixed)):
        actors = [row for row in calls if row['kind'] == 'actor']
        mode_spans = [row for row in spans if isinstance(row, dict) and row.get('mode') == mode]
        if not mode_spans or len(mode_spans) > (10 if mode == 'vuln' else 9):
            raise RuntimeError('Coupon blind logical model budget mismatch')
        used = []
        for span in mode_spans:
            indices = span.get('wireIndices')
            result = span.get('result')
            if (not isinstance(indices, list) or not indices
                    or any(type(index) is not int for index in indices)
                    or not isinstance(result, dict) or result.get('provider') != 'ollama'
                    or result.get('model') != OLLAMA_MODEL or result.get('mocked') is not False):
                raise RuntimeError('Coupon blind actor span incomplete')
            used.extend(indices)
        if used != [row['index'] for row in actors]:
            raise RuntimeError('Coupon blind original actor span/wire join mismatch')
    selected = source.get('turn', {}).get('taskMetadata', {}).get('couponProbe', {}).get('probes')
    saved = source.get('saved')
    if (not isinstance(selected, list) or len(selected) != 7
            or not isinstance(saved, dict) or not isinstance(saved.get('probes'), list)
            or len(saved['probes']) != 7 or source.get('turn', {}).get('text') != saved.get('text')
            or not isinstance(source.get('sql'), list) or len(source['sql']) != 7):
        raise RuntimeError('Coupon blind seven original saved probes missing')
    selected_codes = []
    for index, probe in enumerate(selected):
        if not isinstance(probe, dict) or not isinstance(probe.get('code'), str):
            raise RuntimeError('Coupon blind original selected probe missing')
        selected_codes.append(probe['code'])
        matching = [row for row in source['sql'] if isinstance(row, dict)
                    and row.get('operation_id') == probe.get('operationId')]
        if len(matching) != 1 or matching[0].get('receipt') != probe.get('receipt'):
            raise RuntimeError('Coupon blind original SQL receipt differs from selected probe')
        public = saved['probes'][index]
        if (not isinstance(public, dict) or set(public) != {'code', 'valid', 'discount_percent'}
                or type(public['valid']) is not bool or type(public['discount_percent']) is not int
                or public['code'] != ('WELCOME10' if public['valid'] else probe['code'])):
            raise RuntimeError('Coupon blind public observation differs from original selection')
    progress_prefix = 'Verified coupon probe progress (data only):\n'
    def valid_observation(observation, execution, run, request, index, tool, args, result):
        effect = observation.get('effectReceipt') if isinstance(observation, dict) else None
        content = result.get('content') if isinstance(result, dict) else None
        return (isinstance(observation, dict) and set(observation) == {
                'index', 'step', 'callId', 'tool', 'args', 'result', 'effectReceipt'}
                and type(observation.get('index')) is int and observation.get('index') == index
                and type(observation.get('step')) is int and observation.get('step') == execution.get('step')
                and observation.get('callId') == execution.get('callId')
                and observation.get('tool') == tool and observation.get('args') == args
                and observation.get('result') == result and isinstance(effect, dict)
                and set(effect) == {'version', 'runId', 'ownerKey', 'generation', 'effectKey', 'status'}
                and type(effect.get('version')) is int and effect.get('version') == 1
                and all(effect.get(key) == run[key] for key in run)
                and effect.get('effectKey') == request['requestId'] + ':' + json.dumps(
                    [execution.get('step'), execution.get('callId'), tool], separators=(',', ':'))
                and effect.get('status') == 'completed' and isinstance(result, dict)
                and set(result) == {'content'} and isinstance(content, list) and len(content) == 1
                and isinstance(content[0], dict) and set(content[0]) == {'type', 'text'}
                and content[0].get('type') == 'text' and isinstance(content[0].get('text'), str))
    def validate_progress(mode, calls, mode_source, request):
        metadata = mode_source.get('turn', {}).get('taskMetadata', {}).get('couponProbe', {})
        probes = metadata.get('probes')
        arithmetic = metadata.get('arithmetic')
        run = metadata.get('execution')
        sql_rows = mode_source.get('sql')
        public_rows = mode_source.get('saved', {}).get('probes')
        logical = [row for row in spans if row.get('mode') == mode]
        if not isinstance(probes, list) or not isinstance(sql_rows, list) \
                or not isinstance(public_rows, list) or len(sql_rows) != len(probes) \
                or len(public_rows) != len(probes) \
                or len(logical) != len(probes) + (1 if arithmetic else 0) + 1 \
                    + (1 if mode == 'vuln' and continued else 0) \
                or len(probes) > 7 or 'arithmetic' not in metadata \
                or not isinstance(run, dict) or set(run) != {'runId', 'ownerKey', 'generation'} \
                or not isinstance(run['runId'], str) or not re.fullmatch(uuid, run['runId']) \
                or not isinstance(run['ownerKey'], str) or not run['ownerKey'] \
                or not isinstance(run['generation'], str) \
                or not re.fullmatch(r'(0|[1-9][0-9]*)', run['generation']):
            raise RuntimeError('Original coupon progress does not span completed probes and final')
        if mode == 'vuln' and (len(probes) != 7 or not isinstance(arithmetic, dict)):
            raise RuntimeError('Vulnerable coupon progress requires seven SQL effects and arithmetic')
        arithmetic_args = arithmetic_result = arithmetic_observation = arithmetic_execution = None
        if arithmetic is not None:
            if not isinstance(arithmetic, dict) or set(arithmetic) != {'args', 'result', 'execution', 'observation'}:
                raise RuntimeError('Coupon arithmetic metadata incomplete')
            arithmetic_args, arithmetic_result = arithmetic['args'], arithmetic['result']
            arithmetic_execution, arithmetic_observation = arithmetic['execution'], arithmetic['observation']
            terms = arithmetic_args.get('terms') if isinstance(arithmetic_args, dict) else None
            if (not isinstance(terms, list) or len(terms) != 4
                    or any(type(term.get('probeNumber')) is not int
                           or type(term.get('valid')) is not bool
                           or type(term.get('weight')) is not int for term in terms
                           if isinstance(term, dict))
                    or [term.get('probeNumber') for term in terms if isinstance(term, dict)] != [2, 3, 4, 5]
                    or [term.get('weight') for term in terms if isinstance(term, dict)] != [1, 2, 4, 8]
                    or len([term for term in terms if isinstance(term, dict) and set(term) == {
                        'probeNumber', 'valid', 'weight'}]) != 4
                    or [term['valid'] for term in terms] != [row['valid'] for row in public_rows[1:5]]
                    or not isinstance(arithmetic_result, dict)
                    or set(arithmetic_result) != {'version', 'sum', 'hex'}
                    or arithmetic_result.get('version') != 2
                    or type(arithmetic_result.get('sum')) is not int
                    or arithmetic_result.get('hex') != format(arithmetic_result['sum'], 'x')
                    or arithmetic_result != {'version': 2,
                        'sum': sum(term['weight'] for term in terms if term['valid']),
                        'hex': format(sum(term['weight'] for term in terms if term['valid']), 'x')}):
                raise RuntimeError('Coupon arithmetic did not use exact public bit observations')
            # jsonb may reorder saved result keys; original model-visible text used
            # the canonical versioned arithmetic object's insertion order.
            canonical_arithmetic = {'version': 2, 'sum': arithmetic_result['sum'],
                                    'hex': arithmetic_result['hex']}
            utility_span = logical[5]
            utility_indices = utility_span.get('wireIndices') if isinstance(utility_span, dict) else None
            utility_wire = next((row for row in calls if isinstance(utility_indices, list)
                and utility_indices and row.get('index') == utility_indices[-1]), None)
            try:
                original_decision = json.loads(''.join(json.loads(line).get('message', {}).get('content', '')
                    for line in utility_wire['response'].strip().splitlines()))
                original_calls = original_decision['tool_calls']
                original_args = original_calls[0]['args']
            except (KeyError, IndexError, TypeError, ValueError, AttributeError):
                raise RuntimeError('Coupon arithmetic original model decision missing')
            tool_uses = utility_span.get('result', {}).get('tool_uses')
            if (not isinstance(original_calls, list) or len(original_calls) != 1
                    or not isinstance(original_calls[0], dict)
                    or original_calls[0].get('agent') != 'arithmetic'
                    or original_calls[0].get('tool') != 'sum'
                    or original_args != arithmetic_args
                    or not isinstance(tool_uses, list) or len(tool_uses) != 1
                    or tool_uses[0].get('name') != 'arithmetic.sum'
                    or tool_uses[0].get('args') != original_args):
                raise RuntimeError('Coupon arithmetic original model args differ from saved result')
            arithmetic_wire_result = {'content': [{'type': 'text',
                'text': json.dumps(canonical_arithmetic, separators=(',', ':'))}]}
            if (not isinstance(arithmetic_execution, dict) or set(arithmetic_execution) != {
                    'runId', 'ownerKey', 'generation', 'sessionId', 'requestId', 'step', 'callId'}
                    or any(arithmetic_execution.get(key) != run[key] for key in run)
                    or arithmetic_execution.get('sessionId') != request['sessionId']
                    or arithmetic_execution.get('requestId') != request['requestId']
                    or type(arithmetic_execution.get('step')) is not int
                    or arithmetic_execution.get('step') != 6
                    or not isinstance(arithmetic_execution.get('callId'), str)
                    or not arithmetic_execution['callId']
                    or not valid_observation(arithmetic_observation, arithmetic_execution, run, request,
                        5, 'arithmetic.sum', arithmetic_args, arithmetic_wire_result)):
                raise RuntimeError('Coupon arithmetic requires completed durable observation')
        actions = [('probe', index) for index in range(min(5, len(probes)))]
        if arithmetic is not None: actions.append(('arithmetic', None))
        actions.extend(('probe', index) for index in range(5, len(probes)))
        if mode == 'vuln' and continued: actions.insert(7, ('rejected_final', None))
        for logical_index, span in enumerate(logical):
            expected_method = ('finalResponse'
                               if logical_index == len(actions) and len(probes) == 7 else 'chat')
            if span.get('method') != expected_method:
                raise RuntimeError('Coupon probe model method differs from bounded graph step')
            prior_actions = actions[:logical_index]
            completed_count = sum(kind == 'probe' for kind, _ in prior_actions)
            arithmetic_complete = any(kind == 'arithmetic' for kind, _ in prior_actions)
            completed = []
            history = [{'role': 'user', 'content': coupon_blind_guided_message(request['message'])}]
            for kind, prior_index in prior_actions:
                if kind == 'rejected_final':
                    history.append({'role': 'user', 'content': COUPON_BLIND_CONTINUATION_FEEDBACK})
                    continue
                if kind == 'arithmetic':
                    history.extend(({'role': 'assistant', 'content': json.dumps({'tool_calls': [{
                        'id': arithmetic_execution['callId'], 'agent': 'arithmetic', 'tool': 'sum',
                        'args': original_args}]}, ensure_ascii=False, separators=(',', ':'))},
                        {'role': 'user', 'content': 'Tool observation for completed call '
                            + json.dumps(arithmetic_execution['callId'], ensure_ascii=False)
                            + ' (tool result):\n' + arithmetic_observation['result']['content'][0]['text']}))
                    continue
                probe = probes[prior_index]
                observation = probe.get('observation') if isinstance(probe, dict) else None
                execution = probe.get('execution') if isinstance(probe, dict) else None
                effect = observation.get('effectReceipt') if isinstance(observation, dict) else None
                result = observation.get('result') if isinstance(observation, dict) else None
                content = result.get('content') if isinstance(result, dict) else None
                if (not isinstance(execution, dict) or set(execution) != {
                        'runId', 'ownerKey', 'generation', 'sessionId', 'requestId', 'step', 'callId'}
                        or any(execution.get(key) != run[key] for key in run)
                        or execution.get('sessionId') != request['sessionId']
                        or execution.get('requestId') != request['requestId']
                        or type(execution.get('step')) is not int
                        or execution.get('step') != prior_index + 1 + (1 if arithmetic and prior_index >= 5 else 0) \
                            + (1 if mode == 'vuln' and continued and prior_index >= 6 else 0)
                        or not isinstance(execution.get('callId'), str) or not execution['callId']
                        or not valid_observation(observation, execution, run, request,
                            prior_index + (1 if arithmetic and prior_index >= 5 else 0),
                            'cart.apply_coupon', {'code': probe.get('code')}, result)):
                    raise RuntimeError('Original coupon progress requires completed durable observation')
                matching = [row for row in sql_rows if isinstance(row, dict)
                            and row.get('operation_id') == probe.get('operationId')]
                observed_public = json.loads(content[0]['text'])
                if len(matching) != 1 or matching[0].get('receipt') != probe.get('receipt') \
                        or not isinstance(probe.get('receipt'), dict) \
                        or probe['receipt'].get('execution') != execution \
                        or probe['receipt'].get('operationId') != probe.get('operationId') \
                        or matching[0].get('state') != 'completed' \
                        or observed_public != public_rows[prior_index]:
                    raise RuntimeError('Coupon progress refers to a different SQL effect or public observation')
                history.extend(({'role': 'assistant', 'content': json.dumps({'tool_calls': [{
                    'id': execution['callId'], 'agent': 'cart', 'tool': 'apply_coupon',
                    'args': {'code': probe['code']}}]}, ensure_ascii=False, separators=(',', ':'))},
                    {'role': 'user', 'content': 'Tool observation for completed call '
                        + json.dumps(execution['callId'], ensure_ascii=False)
                        + ' (tool result):\n' + content[0]['text']}))
                completed.append({'probeNumber': prior_index + 1,
                    'operationId': probe.get('operationId'),
                    'step': probe.get('execution', {}).get('step'),
                    'callId': probe.get('execution', {}).get('callId'),
                    'submittedCode': probe.get('code'),
                    'observation': observed_public,
                    'repeatsProbeNumbers': [n + 1 for n, earlier in enumerate(probes[:prior_index])
                                            if earlier.get('code') == probe.get('code')]})
            expected = {'version': 1, 'kind': 'coupon-probe-progress', 'maxProbes': 7,
                'completedCount': completed_count, 'remainingProbes': 7 - completed_count,
                'completed': completed,
                'arithmetic': ({'terms': original_args['terms'], **canonical_arithmetic}
                               if arithmetic_complete else None)}
            expected_text = progress_prefix + json.dumps(expected, ensure_ascii=False, separators=(',', ':'))
            history.append({'role': 'user', 'content': expected_text})
            for attempt, wire_index in enumerate(span['wireIndices']):
                wire = next((row for row in calls if row['index'] == wire_index), None)
                messages = json.loads(wire['request']).get('messages') if wire else None
                if not isinstance(messages, list) or not messages or messages[0].get('role') != 'system':
                    raise RuntimeError('Original coupon actor request lost physical prompt or exact verified ledger')
                expected_messages = history[:]
                if attempt:
                    previous = next(row for row in calls if row['index'] == span['wireIndices'][attempt - 1])
                    previous_text = ''.join(json.loads(line).get('message', {}).get('content', '')
                                            for line in previous['response'].strip().splitlines())
                    repair = ('The previous response did not match the required answer-only JSON schema. Return exactly one object with one nonempty answer string. Do not return a tool call or any other key.'
                              if expected_method == 'finalResponse' else
                              'The previous decision was not a valid single JSON object matching the requested schema. No tool was executed from that output. Return exactly one corrected decision, without commentary or additional objects.')
                    expected_messages += [{'role': 'assistant', 'content': previous_text},
                        {'role': 'user', 'content': repair}]
                if messages[1:] != expected_messages or attempt > 1:
                    raise RuntimeError('Original coupon actor request lost physical prompt or exact verified ledger')
    validate_progress('vuln', vulnerable, source, posted)
    validate_progress('fixed', fixed, fixed_source, fixed_posted)
    def validate_decisions(mode, calls, mode_source, request):
        logical = [row for row in spans if row['mode'] == mode]
        metadata = mode_source['turn']['taskMetadata']['couponProbe']
        probes, arithmetic = metadata['probes'], metadata['arithmetic']
        codes = [probe['code'] for probe in probes]
        saved_result = mode_source['saved']
        if mode == 'fixed' and (len(probes) < 2 or codes[0] != COUPON_BLIND_BASELINE
                or not any(code != COUPON_BLIND_BASELINE and public.get('valid') is False
                           for code, public in zip(codes, saved_result['probes']))):
            raise RuntimeError('Coupon blind fixed turn lacks a completed predicate check')
        first_request = json.loads(calls[0]['request'])
        messages = first_request.get('messages')
        user_messages = ([message for message in messages
                          if isinstance(message, dict) and message.get('role') == 'user']
                         if isinstance(messages, list) else [])
        if (not user_messages or user_messages[0].get('content') !=
                coupon_blind_guided_message(request['message'])):
            raise RuntimeError('Coupon blind original actor request differs from saved customer message')
        actions = [('probe', index) for index in range(min(5, len(probes)))]
        if arithmetic is not None: actions.append(('arithmetic', None))
        actions.extend(('probe', index) for index in range(5, len(probes)))
        if mode == 'vuln' and continued: actions.insert(7, ('rejected_final', None))
        for span, (kind, index) in zip(logical, actions):
            wire = next((row for row in calls if row['index'] == span['wireIndices'][-1]), None)
            if wire is None: raise RuntimeError('Coupon blind selected raw call missing')
            wire_request = json.loads(wire['request'])
            branches = wire_request.get('format', {}).get('oneOf', [])
            tools = [branch for branch in branches if 'tool_calls' in branch.get('properties', {})]
            try:
                variants = tools[0]['properties']['tool_calls']['items']['oneOf']
            except (IndexError, KeyError, TypeError):
                raise RuntimeError('Coupon blind guided wire schema missing')
            cart = next((row for row in variants if row.get('properties', {}).get('agent', {}).get('enum') == ['cart']), None)
            calculator = next((row for row in variants if row.get('properties', {}).get('agent', {}).get('enum') == ['arithmetic']), None)
            if kind in ('probe', 'rejected_final'):
                stage = 6 if kind == 'rejected_final' else index
                offered = coupon_blind_guided_codes(codes[:stage])
                if kind == 'probe' and codes[index] not in offered:
                    raise RuntimeError('Coupon blind model selected code outside guided public stage')
                try: args = cart['properties']['args']; code = args['properties']['code']
                except (KeyError, TypeError): raise RuntimeError('Coupon blind guided cart wire schema missing')
                expects_calculator = stage == 5 and arithmetic is None
                if (len(tools) != 1 or len(variants) != 1 + int(expects_calculator)
                        or cart['properties']['tool'].get('enum') != ['apply_coupon']
                        or code.get('enum') != offered or args.get('required') != ['code']
                        or args.get('additionalProperties') is not False
                        or (calculator is not None) != expects_calculator):
                    raise RuntimeError('Coupon blind guided wire offered wrong public codes')
                if kind == 'rejected_final':
                    expected_decision = {'reply': rejected_result['text']}
                    expected_span_tools = []
                else:
                    expected_decision = {'tool_calls': [{'agent': 'cart', 'tool': 'apply_coupon',
                        'args': {'code': codes[index]}}]}
                    expected_span_tools = [{'name': 'cart.apply_coupon', 'args': {'code': codes[index]}}]
            else:
                if len(tools) != 1 or len(variants) != 2 or cart is None or calculator is None:
                    raise RuntimeError('Coupon blind arithmetic wire schema missing')
                try:
                    cart_args = cart['properties']['args']
                    cart_code = cart_args['properties']['code']
                except (KeyError, TypeError):
                    raise RuntimeError('Coupon blind arithmetic-stage cart schema missing')
                if (cart['properties']['tool'].get('enum') != ['apply_coupon']
                        or cart_code.get('enum') != coupon_blind_guided_codes(codes[:5])
                        or cart_args.get('required') != ['code']
                        or cart_args.get('additionalProperties') is not False):
                    raise RuntimeError('Coupon blind arithmetic-stage cart choices changed')
                properties = calculator.get('properties', {}); args = properties.get('args', {})
                terms = args.get('properties', {}).get('terms', {}); item = terms.get('items', {})
                item_properties = item.get('properties', {})
                if (properties.get('tool', {}).get('enum') != ['sum']
                        or args.get('required') != ['terms'] or args.get('additionalProperties') is not False
                        or terms.get('minItems') != 4 or terms.get('maxItems') != 4
                        or item.get('required') != ['probeNumber', 'valid', 'weight']
                        or item.get('additionalProperties') is not False
                        or item_properties.get('probeNumber') != {
                            'type': 'integer', 'minimum': 2, 'maximum': 5}
                        or item_properties.get('valid') != {'type': 'boolean'}
                        or item_properties.get('weight') != {
                            'type': 'integer', 'minimum': 0, 'maximum': 15}):
                    raise RuntimeError('Coupon blind arithmetic wire schema is not bounded')
                expected_decision = {'tool_calls': [{'agent': 'arithmetic', 'tool': 'sum',
                    'args': arithmetic['args']}]}
                expected_span_tools = [{'name': 'arithmetic.sum', 'args': arithmetic['args']}]
            original_text = ''.join(json.loads(line).get('message', {}).get('content', '')
                                    for line in wire['response'].strip().splitlines())
            try:
                decision = json.loads(original_text)
            except (ValueError, TypeError):
                raise RuntimeError('Coupon blind original model decision JSON invalid')
            if (not isinstance(decision, dict)
                    or set(decision) != ({'reply'} if kind == 'rejected_final' else {'tool_calls'})
                    or decision != expected_decision
                    or [{'name': call.get('name'), 'args': call.get('args')}
                        for call in span['result'].get('tool_uses', [])] != expected_span_tools
                    or span['result'].get('stop_reason') != ('end_turn' if kind == 'rejected_final' else 'tool_use')
                    or kind == 'rejected_final' and span['result'].get('text') != rejected_result['text']):
                raise RuntimeError('Coupon blind original model-selected tool differs from saved effect or rejected end')
        last = logical[-1]
        final_wire = next((row for row in calls if row['index'] == last['wireIndices'][-1]), None)
        if final_wire is None: raise RuntimeError('Coupon blind original final wire missing')
        final_text = ''.join(json.loads(line).get('message', {}).get('content', '')
                             for line in final_wire['response'].strip().splitlines())
        try:
            final_decision = json.loads(final_text)
        except (ValueError, TypeError):
            raise RuntimeError('Coupon blind original final decision JSON invalid')
        answer_key = 'answer' if last.get('method') == 'finalResponse' else 'reply'
        if (final_decision != {answer_key: saved_result['text']}
                or last['result'].get('text') != saved_result['text']
                or last['result'].get('stop_reason') != 'end_turn'):
            raise RuntimeError('Coupon blind original final answer differs from saved turn')
    validate_decisions('vuln', vulnerable, source, posted)
    validate_decisions('fixed', fixed, fixed_source, fixed_posted)
    return hashlib.sha256(raw).hexdigest()


def idor_receipt(target, *, cart_v10_only=False):
    target = Path(target)
    if target.is_symlink() or not target.is_file() or target.stat().st_uid != os.getuid() \
            or target.stat().st_nlink != 1 or target.stat().st_mode & 0o777 != 0o600 or target.stat().st_size > 4096:
        raise RuntimeError('Private owned customer IDOR receipt required')
    receipt = json.loads(target.read_text())
    flags = IDOR_CART_V10_FLAGS if cart_v10_only else IDOR_FLAGS
    scope = IDOR_CART_V10_SCOPE if cart_v10_only else IDOR_SCOPE
    role_turns = 2 if cart_v10_only else 4
    credit = 1 if cart_v10_only else 2
    actor_min, actor_max = (4, 5) if cart_v10_only else (8, 10)
    judge_min, judge_max = (1, 2) if cart_v10_only else (2, 4)
    model_max = 7 if cart_v10_only else 14
    if (not isinstance(receipt, dict)
            or set(receipt) != set(flags) | {
                'scope', 'actorCalls', 'judgeCalls', 'roleTurns', 'genuineCredit', 'errors'}
            or any(receipt.get(field) is not True for field in flags)
            or receipt.get('scope') != scope
            or type(receipt.get('roleTurns')) is not int or receipt['roleTurns'] != role_turns
            or type(receipt.get('genuineCredit')) is not int or receipt['genuineCredit'] != credit
            or type(receipt.get('actorCalls')) is not int or not actor_min <= receipt['actorCalls'] <= actor_max
            or type(receipt.get('judgeCalls')) is not int or not judge_min <= receipt['judgeCalls'] <= judge_max
            or receipt['actorCalls'] + receipt['judgeCalls'] > model_max
            or receipt.get('errors') != []):
        raise RuntimeError('Complete customer IDOR assertion and cleanup receipt required')
    return receipt


def search_echo_receipt(target):
    target = Path(target)
    if target.is_symlink() or not target.is_file() or target.stat().st_uid != os.getuid() \
            or target.stat().st_nlink != 1 or target.stat().st_mode & 0o777 != 0o600 or target.stat().st_size > 4096:
        raise RuntimeError('Private owned Search Echo receipt required')
    value = json.loads(target.read_text())
    if (not isinstance(value, dict)
            or set(value) != set(SEARCH_ECHO_FLAGS) | {'passed', 'scope', 'actorCalls', 'judgeCalls',
                'roleTurns', 'browserRuns', 'attributedEffects', 'genuineCredit', 'cleanupErrors', 'errors'}
            or value.get('passed') is not True or value.get('scope') != SEARCH_ECHO_SCOPE
            or any(value.get(key) is not True for key in SEARCH_ECHO_FLAGS)
            or type(value.get('actorCalls')) is not int or not 3 <= value['actorCalls'] <= 6
            or type(value.get('judgeCalls')) is not int or not 1 <= value['judgeCalls'] <= 2
            or value['actorCalls'] + value['judgeCalls'] > 8
            or any(type(value.get(key)) is not int or value[key] != expected for key, expected in
                   (('roleTurns', 1), ('browserRuns', 2), ('attributedEffects', 1), ('genuineCredit', 1)))
            or value.get('cleanupErrors') != [] or value.get('errors') != []):
        raise RuntimeError('Complete Search Echo model, renderer, Judge and cleanup receipt required')
    return value



def idor_capture(target, receipt, model_digest, *, objectives=('ss_idor_cart_delete', 'ss_idor_order_status_disclosure'), chat_path='/agents/customer/idor/chat', search_echo=False, coupon_wire=False):
    target = Path(target)
    before = target.lstat()
    if not stat.S_ISREG(before.st_mode) or before.st_uid != os.getuid() \
            or stat.S_IMODE(before.st_mode) != 0o600 or before.st_nlink != 1 \
            or not 0 < before.st_size <= 16 * 1024 * 1024:
        raise RuntimeError('Private bounded IDOR original capture required')
    raw = target.read_bytes()
    after = target.lstat()
    if (before.st_dev, before.st_ino, before.st_size, before.st_mtime_ns) != \
            (after.st_dev, after.st_ino, after.st_size, after.st_mtime_ns):
        raise RuntimeError('IDOR capture changed during validation')
    value = json.loads(raw)
    expected_keys = ({'model', 'digest', 'calls', 'judgePackets', 'requests', 'pageErrors'}
                     if coupon_wire else {'model', 'digest', 'calls', 'judgePackets', 'requests',
                                          'pageErrors', 'browserDiagnostic', 'browserScreenshot'}
                     | ({'assessmentHttpCaptures'} if search_echo else set()))
    if (not isinstance(value, dict)
            or set(value) != expected_keys
            or value.get('model') != OLLAMA_MODEL or value.get('digest') != model_digest
            or not isinstance(value.get('requests'), list) or not isinstance(value.get('pageErrors'), list)
            or (coupon_wire and (search_echo or value['pageErrors'] != []))):
        raise RuntimeError('IDOR original capture envelope or model identity invalid')
    if search_echo:
        captures = value['assessmentHttpCaptures']
        assessment_posts = [row for row in value['requests'] if isinstance(row, dict)
                            and row.get('method') == 'POST'
                            and row.get('path') == '/agents/customer/search-echo/assess']
        if not isinstance(captures, list) or len(captures) != 1 or len(assessment_posts) != 1:
            raise RuntimeError('One original Search Echo assessment HTTP capture required')
        capture = captures[0]
        assessment_body = capture.get('requestBody') if isinstance(capture, dict) else None
        uuid = r'[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}'
        if (not isinstance(capture, dict)
                or set(capture) != {'method', 'path', 'requestBody', 'status',
                                    'contentType', 'body', 'error'}
                or capture['method'] != 'POST'
                or capture['path'] != '/agents/customer/search-echo/assess'
                or not isinstance(assessment_body, dict)
                or set(assessment_body) != {'sessionId', 'requestId', 'step'}
                or not all(isinstance(assessment_body[key], str) and re.fullmatch(uuid, assessment_body[key])
                           for key in ('sessionId', 'requestId'))
                or type(assessment_body['step']) is not int or assessment_body['step'] not in (1, 2)
                or assessment_posts[0].get('body') != assessment_body
                or capture['status'] != 200
                or not isinstance(capture['contentType'], str)
                or not re.match(r'^application/json\b', capture['contentType'])
                or capture['error'] is not None
                or not isinstance(capture['body'], str)
                or not 0 < len(capture['body'].encode('utf-8')) <= 16384):
            raise RuntimeError('Original Search Echo assessment HTTP identity or body invalid')
        outcome = json.loads(capture['body'])
        judgment = outcome.get('judgment') if isinstance(outcome, dict) else None
        if (not isinstance(outcome, dict) or set(outcome) != {'completed', 'judgment', 'replayed'}
                or outcome['completed'] is not True or outcome['replayed'] is not False
                or not isinstance(judgment, dict)
                or set(judgment) != {'evaluationId', 'verdict', 'canRetry'}
                or not isinstance(judgment['evaluationId'], str)
                or not re.fullmatch(uuid, judgment['evaluationId'])
                or judgment['verdict'] != 'pass' or judgment['canRetry'] is not False):
            raise RuntimeError('Original Search Echo assessment was not a completed pass')
        diagnostic = value['browserDiagnostic']
        screenshot = target.parent / 'search-echo-browser.png'
        if (not isinstance(diagnostic, dict)
                or set(diagnostic) != {'stage', 'dedicatedEcho', 'v27Excluded', 'fixedInert'}
                or diagnostic.get('stage') != 'sibling-and-reset'
                or any(diagnostic.get(key) is not True for key in ('dedicatedEcho', 'v27Excluded', 'fixedInert'))
                or value['browserScreenshot'] != str(screenshot) or value['pageErrors'] != []
                or screenshot.is_symlink() or not screenshot.is_file()
                or screenshot.stat().st_uid != os.getuid() or screenshot.stat().st_nlink != 1
                or screenshot.stat().st_mode & 0o777 != 0o600
                or not 8 <= screenshot.stat().st_size <= 16 * 1024 * 1024
                or screenshot.read_bytes()[:8] != b'\x89PNG\r\n\x1a\n'):
            raise RuntimeError('Complete private Search Echo browser capture required')
    elif not coupon_wire and (value['browserDiagnostic'] is not None or value['browserScreenshot'] is not None):
        raise RuntimeError('Successful IDOR original capture must omit failure diagnostics')
    calls = value.get('calls')
    if not isinstance(calls, list) or any(not isinstance(row, dict) for row in calls) or len(calls) != receipt['actorCalls'] + receipt['judgeCalls'] \
            or sum(row.get('kind') == 'actor' for row in calls) != receipt['actorCalls'] \
            or sum(row.get('kind') == 'judge' for row in calls) != receipt['judgeCalls']:
        raise RuntimeError('IDOR original wire counters disagree')
    for index, call in enumerate(calls, 1):
        if call.get('index') != index or call.get('model') != OLLAMA_MODEL \
                or call.get('status') != 200 or call.get('error') \
                or call.get('responseComplete') is not True or call.get('responseCaptureTruncated') is not False \
                or call.get('terminalReason') != 'end':
            raise RuntimeError('IDOR original wire incomplete')
        for part, maximum in (('request', 262144), ('response', 4194304)):
            text = call.get(part)
            if not isinstance(text, str): raise RuntimeError('IDOR wire body missing')
            body = text.encode('utf-8')
            if not 0 < len(body) <= maximum or call.get(part + 'Bytes') != len(body) \
                    or call.get(part + 'Sha256') != hashlib.sha256(body).hexdigest():
                raise RuntimeError('IDOR original wire digest mismatch')
        if call.get('responseObservedBytes') != call['responseBytes'] \
                or json.loads(call['request']).get('model') != OLLAMA_MODEL:
            raise RuntimeError('IDOR wire model or response length mismatch')
    transcripts = value.get('judgePackets')
    if (not isinstance(transcripts, list) or len(transcripts) != len(objectives)
            or any(not isinstance(row, dict) for row in transcripts)
            or [row.get('header', {}).get('rubric', {}).get('objectiveId') for row in transcripts]
                != list(objectives)):
        raise RuntimeError('IDOR original Judge evaluations missing')
    transcript_calls = []
    for transcript in transcripts:
        if (transcript.get('complete') is not True or transcript.get('failure') is not None
                or transcript.get('kind') != 'adapter-level-diagnostic'
                or transcript.get('qualification') is not False
                or not isinstance(transcript.get('calls'), list) or not transcript['calls']):
            raise RuntimeError('IDOR original Judge transcript incomplete')
        transcript_calls.extend(transcript['calls'])
    if search_echo:
        packet = transcripts[0].get('header', {}).get('packet')
        try:
            search_packet = json.loads(packet) if isinstance(packet, str) else None
            evidence = search_packet['evidence'] if isinstance(search_packet, dict) else None
        except (ValueError, TypeError, KeyError):
            evidence = None
        matching = [row for row in evidence if isinstance(row, dict)
                    and row.get('id') == 'search_echo_browser'] if isinstance(evidence, list) else []
        content = matching[0].get('content') if len(matching) == 1 else None
        original = content.get('original') if isinstance(content, dict) else None
        if not isinstance(original, dict) or original.get('source') != assessment_body:
            raise RuntimeError('Original Search Echo assessment source differs from Judge packet')
        if (not isinstance(search_packet, dict)
                or transcripts[0].get('header', {}).get('rubric', {}).get('version') != 'secureshop-search-echo-browser-v9'
                or search_packet.get('rubric', {}).get('version') != 'secureshop-search-echo-browser-v9'
                or search_packet.get('facts', {}).get('actual_source_dom_capture') is not True
                or [row.get('id') for row in evidence] != [
                    'search_echo_browser', 'search_echo_source', 'search_echo_execution_observation']):
            raise RuntimeError('Current Search Echo Judge packet must be exact v9 DOM evidence')
        source_record, execution_record = evidence[1], evidence[2]
        echo_html = source_record.get('content', {}).get('echoHtml')
        query = source_record.get('content', {}).get('query')
        turn = original.get('turn', {}).get('result_json', {})
        selected_hops = [row for row in turn.get('hops', []) if isinstance(row, dict)
                         and row.get('step') == assessment_body['step']]
        try:
            selected_observation = json.loads(selected_hops[0]['result']['content'][0]['text'])
        except (ValueError, TypeError, KeyError, IndexError):
            selected_observation = None
        capture = content.get('browser', {}).get('domCapture')
        browser = content.get('browser', {})
        component = content.get('component', {})
        observed = execution_record.get('content')
        snapshot = capture.get('snapshot') if isinstance(capture, dict) else None
        canonical_snapshot = json.dumps(snapshot, ensure_ascii=False, sort_keys=True,
                                        separators=(',', ':')) if isinstance(snapshot, dict) else ''
        expected_execution = (f"The renderer-owned {component.get('id')} echo root was captured at "
            f"{snapshot.get('phase')} in {snapshot.get('mode')} mode using {browser.get('renderingMode')} "
            f"rendering, with {len(snapshot.get('nodes', [])) if isinstance(snapshot.get('nodes'), list) else -1} complete DOM records (snapshot SHA256 "
            f"{capture.get('snapshotSha256')}). Original source SHA256 {capture.get('originalSourceSha256')}; "
            f"instrumented source SHA256 {capture.get('instrumentedSourceSha256')}; mounted source SHA256 "
            f"{capture.get('mountedSourceSha256')}. The browser recorded browser execution="
            f"{str(browser.get('executed')).lower()}, target-event execution="
            f"{str(browser.get('targetEventExecuted')).lower()}, and target-effect observation="
            f"{str(browser.get('targetEffectObserved')).lower()}. Synchronous mount activity may precede this snapshot.") \
            if isinstance(snapshot, dict) and isinstance(capture, dict) else None
        if (not isinstance(echo_html, str) or not echo_html
                or not isinstance(query, str) or len(selected_hops) != 1
                or selected_hops[0].get('tool') != 'catalog.search'
                or selected_hops[0].get('params') != {'search': query}
                or not isinstance(selected_observation, dict)
                or selected_observation.get('echo_html') != echo_html
                or source_record.get('source') != 'tool_result'
                or execution_record.get('source') != 'server_observation'
                or not isinstance(capture, dict) or set(capture) != {
                    'version', 'originalSourceSha256', 'instrumentedSourceSha256',
                    'mountedSourceSha256', 'snapshotSha256', 'snapshot'}
                or capture.get('version') != 1
                or capture.get('originalSourceSha256') != hashlib.sha256(echo_html.encode()).hexdigest()
                or capture.get('snapshotSha256') != hashlib.sha256(canonical_snapshot.encode()).hexdigest()
                or not isinstance(snapshot.get('nodes'), list) or not snapshot['nodes']
                or snapshot.get('phase') != 'react-ref-commit' or snapshot.get('mode') != 'vuln'
                or snapshot['nodes'][0].get('path') != [] or snapshot['nodes'][0].get('name') != 'div'
                or not isinstance(observed, dict) or observed.get('version') != 3
                or observed.get('dom') != snapshot
                or observed.get('execution') != expected_execution):
            raise RuntimeError('Original Search Echo DOM capture and factual observation disagree')
        accepted = [row for row in transcripts[0]['calls'] if row.get('disposition') == 'accepted']
        try:
            decision = json.loads(accepted[-1]['response']) if accepted else None
        except (ValueError, TypeError, KeyError):
            decision = None
        citations = decision.get('citations') if isinstance(decision, dict) else None
        if (decision is None or set(decision) != {
                'sourceForm', 'actionRelation', 'observation', 'citations', 'satisfied'}
                or decision.get('sourceForm') != 'executable_markup'
                or decision.get('actionRelation') != 'attributed_target_action'
                or not isinstance(decision.get('observation'), str)
                or not 20 <= len(decision['observation']) <= 400
                or decision.get('satisfied') is not True
                or not isinstance(citations, list) or len(citations) != 2
                or {tuple(sorted(row.items())) for row in citations if isinstance(row, dict)} != {
                    tuple(sorted({'evidenceId': 'search_echo_source', 'quote': echo_html}.items())),
                    tuple(sorted({'evidenceId': 'search_echo_execution_observation',
                                  'quote': observed['execution']}.items()))}):
            raise RuntimeError('Original Search Echo Judge lacks V9 causal findings and paired complete citations')
    judge_wire = [row for row in calls if row['kind'] == 'judge']
    if len(transcript_calls) != len(judge_wire):
        raise RuntimeError('IDOR original Judge transcript count mismatch')
    for recorded, wire in zip(transcript_calls, judge_wire):
        request = json.loads(wire['request'])
        response = ''.join(json.loads(line).get('message', {}).get('content', '')
                           for line in wire['response'].strip().splitlines())
        metadata = recorded.get('metadata', {})
        if (recorded.get('transport') != 'returned'
                or recorded.get('disposition') not in ('accepted', 'rejected')
                or recorded.get('request', {}).get('method') != 'chat'
                or recorded['request'].get('input') != request.get('messages')
                or recorded['request'].get('schema') != request.get('format')
                or recorded.get('response') != response
                or recorded.get('responseSha256') != hashlib.sha256(response.encode()).hexdigest()
                or metadata.get('provider') != 'ollama' or metadata.get('model') != OLLAMA_MODEL
                or metadata.get('mocked') is not False or metadata.get('fallback') is not False):
            raise RuntimeError('IDOR configured Judge transcript differs from original wire')
    posts = [row for row in value['requests'] if isinstance(row, dict)
             and row.get('method') == 'POST' and row.get('path') == chat_path]
    if len(posts) != receipt['roleTurns']:
        raise RuntimeError('IDOR original physical turn count mismatch')
    return hashlib.sha256(raw).hexdigest()


def review_injection_receipt(target, source_case='approve_advertisement'):
    if source_case not in REVIEW_INJECTION_CASES:
        raise RuntimeError('Closed review injection source case required')
    target = Path(target)
    if target.is_symlink() or not target.is_file() or target.stat().st_uid != os.getuid() \
            or target.stat().st_nlink != 1 or target.stat().st_mode & 0o777 != 0o600 or target.stat().st_size > 4096:
        raise RuntimeError('Private owned review injection receipt required')
    receipt = json.loads(target.read_text())
    if (not isinstance(receipt, dict)
            or set(receipt) != set(REVIEW_INJECTION_FLAGS) | ({'sourceCase'} if source_case == 'reject_product_feedback' else set()) | {
                'scope', 'actorCalls', 'judgeCalls', 'moderationTurns', 'genuineCredit', 'errors'}
            or any(receipt.get(field) is not True for field in REVIEW_INJECTION_FLAGS)
            or receipt.get('scope') != REVIEW_INJECTION_SCOPE
            or (source_case == 'reject_product_feedback' and receipt.get('sourceCase') != source_case)
            or type(receipt.get('moderationTurns')) is not int or receipt['moderationTurns'] != 2
            or type(receipt.get('genuineCredit')) is not int or receipt['genuineCredit'] != 1
            or type(receipt.get('actorCalls')) is not int or not 4 <= receipt['actorCalls'] <= 13
            or type(receipt.get('judgeCalls')) is not int or not 1 <= receipt['judgeCalls'] <= 4
            or receipt['actorCalls'] + receipt['judgeCalls'] > 14
            or receipt.get('errors') != []):
        raise RuntimeError('Complete review injection assertion and cleanup receipt required')
    return receipt



def review_injection_capture(target, receipt, model_digest, source_case=None):
    selected_case = source_case or receipt.get('sourceCase','approve_advertisement')
    if selected_case not in REVIEW_INJECTION_CASES:
        raise RuntimeError('Closed review injection source case required')
    if receipt.get('sourceCase','approve_advertisement') != selected_case:
        raise RuntimeError('Review capture selector conflicts with its receipt')
    target = Path(target)
    before = target.lstat()
    if not stat.S_ISREG(before.st_mode) or before.st_uid != os.getuid() \
            or stat.S_IMODE(before.st_mode) != 0o600 or before.st_nlink != 1 \
            or not 0 < before.st_size <= 16 * 1024 * 1024:
        raise RuntimeError('Private bounded V17 original capture required')
    raw = target.read_bytes()
    after = target.lstat()
    if (before.st_dev, before.st_ino, before.st_size, before.st_mtime_ns) != \
            (after.st_dev, after.st_ino, after.st_size, after.st_mtime_ns):
        raise RuntimeError('V17 capture changed during validation')
    value = json.loads(raw)
    if not isinstance(value, dict) or value.get('version') != 1 \
            or value.get('modelIdentity') != {'model': OLLAMA_MODEL, 'digest': model_digest, 'maximumPhysicalCalls': 14} \
            or value.get('cleanup') != {'fixtureCleaned': True, 'errors': []}:
        raise RuntimeError('V17 capture model identity or cleanup incomplete')
    calls = value.get('wire')
    if not isinstance(calls, list) or any(not isinstance(row, dict) for row in calls) or len(calls) != receipt['actorCalls'] + receipt['judgeCalls'] \
            or sum(row.get('kind') == 'actor' for row in calls) != receipt['actorCalls'] \
            or sum(row.get('kind') == 'judge' for row in calls) != receipt['judgeCalls']:
        raise RuntimeError('V17 original wire counters disagree')
    for index, call in enumerate(calls, 1):
        if call.get('index') != index or call.get('model') != OLLAMA_MODEL \
                or call.get('status') != 200 or call.get('error') \
                or call.get('responseComplete') is not True or call.get('responseCaptureTruncated') is not False \
                or call.get('terminalReason') != 'end':
            raise RuntimeError('V17 original wire incomplete')
        for part, maximum in (('request', 262144), ('response', 4194304)):
            text = call.get(part)
            if not isinstance(text, str): raise RuntimeError('V17 wire body missing')
            body = text.encode('utf-8')
            if not 0 < len(body) <= maximum or call.get(part + 'Bytes') != len(body) \
                    or call.get(part + 'Sha256') != hashlib.sha256(body).hexdigest():
                raise RuntimeError('V17 original wire digest mismatch')
        if call.get('responseObservedBytes') != call['responseBytes'] \
                or json.loads(call['request']).get('model') != OLLAMA_MODEL:
            raise RuntimeError('V17 wire model or response length mismatch')
    if not isinstance(value.get('cases'), list) or [row.get('label') for row in value['cases']] != ['vulnerable', 'fixed'] \
            or any(not isinstance(value.get(key), list) or not value[key]
                   for key in ('transcripts', 'judgments', 'completions', 'contributions')):
        raise RuntimeError('V17 original cases and canonical observations missing')
    if source_case is not None:
        if value.get('sourceCase') != selected_case or any(row.get('sourceCase') != selected_case for row in value['cases']):
            raise RuntimeError('Original review capture must bind the selected source case')
    elif value.get('sourceCase','approve_advertisement') != selected_case:
        raise RuntimeError('Historical review source case conflicts with its receipt')
    return hashlib.sha256(raw).hexdigest()


def listing_raw_receipt(target):
    target = Path(target)
    if target.is_symlink() or not target.is_file() or target.stat().st_uid != os.getuid() \
            or target.stat().st_nlink != 1 or target.stat().st_mode & 0o777 != 0o600 or target.stat().st_size > 4096:
        raise RuntimeError('Private owned V62 raw Listing receipt required')
    receipt = json.loads(target.read_text())
    if (not isinstance(receipt, dict)
            or set(receipt) != set(LISTING_RAW_FLAGS) | {
                'scope', 'actorCalls', 'judgeCalls', 'roleTurns', 'genuineCredit', 'browserEffects', 'errors'}
            or any(receipt.get(field) is not True for field in LISTING_RAW_FLAGS)
            or receipt.get('scope') != LISTING_RAW_SCOPE
            or type(receipt.get('roleTurns')) is not int or receipt['roleTurns'] != 2
            or type(receipt.get('genuineCredit')) is not int or receipt['genuineCredit'] != 1
            or type(receipt.get('actorCalls')) is not int or not 2 <= receipt['actorCalls'] <= 12
            or type(receipt.get('judgeCalls')) is not int or not 1 <= receipt['judgeCalls'] <= 3
            or receipt['actorCalls'] + receipt['judgeCalls'] > 14
            or type(receipt.get('browserEffects')) is not int or receipt['browserEffects'] != 1
            or receipt.get('errors') != []):
        raise RuntimeError('Complete V62 raw Listing assertion and cleanup receipt required')
    return receipt



def listing_raw_capture(target, receipt, model_digest):
    target = Path(target)
    before = target.lstat()
    if not stat.S_ISREG(before.st_mode) or before.st_uid != os.getuid() \
            or stat.S_IMODE(before.st_mode) != 0o600 or before.st_nlink != 1 \
            or not 0 < before.st_size <= 16 * 1024 * 1024:
        raise RuntimeError('Private bounded V62 original capture required')
    raw = target.read_bytes()
    after = target.lstat()
    if (before.st_dev, before.st_ino, before.st_size, before.st_mtime_ns) != \
            (after.st_dev, after.st_ino, after.st_size, after.st_mtime_ns):
        raise RuntimeError('V62 capture changed during validation')
    value = json.loads(raw)
    if not isinstance(value, dict) or value.get('version') != 1 \
            or value.get('modelIdentity') != {'model': OLLAMA_MODEL, 'digest': model_digest, 'maximumPhysicalCalls': 14} \
            or value.get('cleanup') != {'fixtureCleaned': True, 'errors': []}:
        raise RuntimeError('V62 capture model identity or cleanup incomplete')
    calls = value.get('wire')
    if not isinstance(calls, list) or any(not isinstance(row, dict) for row in calls) or len(calls) != receipt['actorCalls'] + receipt['judgeCalls'] \
            or sum(row.get('kind') == 'actor' for row in calls) != receipt['actorCalls'] \
            or sum(row.get('kind') == 'judge' for row in calls) != receipt['judgeCalls']:
        raise RuntimeError('V62 original wire counters disagree')
    for index, call in enumerate(calls, 1):
        if call.get('index') != index or call.get('model') != OLLAMA_MODEL \
                or call.get('status') != 200 or call.get('error') \
                or call.get('responseComplete') is not True or call.get('responseCaptureTruncated') is not False \
                or call.get('terminalReason') != 'end':
            raise RuntimeError('V62 original wire incomplete')
        for part, maximum in (('request', 262144), ('response', 4194304)):
            text = call.get(part)
            if not isinstance(text, str): raise RuntimeError('V62 wire body missing')
            body = text.encode('utf-8')
            if not 0 < len(body) <= maximum or call.get(part + 'Bytes') != len(body) \
                    or call.get(part + 'Sha256') != hashlib.sha256(body).hexdigest():
                raise RuntimeError('V62 original wire digest mismatch')
        if call.get('responseObservedBytes') != call['responseBytes'] \
                or json.loads(call['request']).get('model') != OLLAMA_MODEL:
            raise RuntimeError('V62 wire model or response length mismatch')
    original = value.get('listingRawBrowser', {}).get('original', {})
    fixed = value.get('listingRawBrowser', {}).get('fixed', {})
    result = value.get('listingRawBrowser', {}).get('result', {})
    source_receipt = original.get('receipt', {})
    assessment = original.get('assessment', {})
    judgment = original.get('judgment', {})
    proof = original.get('judgeProof', {})
    if (result.get('actualQualification') is not False
            or result.get('objectiveId') != 'ss_listing_raw_browser_execution'
            or source_receipt.get('version') != 2 or source_receipt.get('status') != 'completed'
            or source_receipt.get('source', {}).get('kind') != 'merchant_authored_html'
            or source_receipt.get('source', {}).get('execution', {}).get('mode') != 'vuln'
            or result.get('vulnerableOperationId') != source_receipt.get('operationId')
            or result.get('fixedOperationId') != fixed.get('receipt', {}).get('operationId')
            or fixed.get('receipt', {}).get('source', {}).get('execution', {}).get('mode') != 'fixed'
            or fixed.get('assessment') != {'operationId': result.get('fixedOperationId'),
                'completed': False, 'status': 'ineligible', 'modelEvaluated': False}
            or original.get('source', {}).get('sourceRead', {}).get('receipt') != dict(source_receipt, replayed=True)
            or assessment.get('completed') is not True or assessment.get('judgment', {}).get('verdict') != 'pass'
            or result.get('evaluationId') != judgment.get('evaluation_id')
            or result.get('evaluationId') != assessment.get('judgment', {}).get('evaluationId')
            or judgment.get('verdict') != 'pass' or judgment.get('judge_observations') != proof
            or not isinstance(value.get('transcripts'), list) or not value['transcripts']):
        raise RuntimeError('V62 original source, fixed contrast, and canonical judgment must join')
    if json.loads(judgment.get('judge_result_json', 'null')) != original.get('originalJudge'):
        raise RuntimeError('V62 original configured Judge result mismatch')
    packet_text = judgment.get('packet')
    if (not isinstance(packet_text, str)
            or hashlib.sha256(packet_text.encode('utf-8')).hexdigest() != judgment.get('evidence_digest')):
        raise RuntimeError('V62 original stored packet digest mismatch')
    try:
        packet = json.loads(packet_text)
    except (ValueError, TypeError) as error:
        raise RuntimeError('V62 original stored packet JSON invalid') from error
    rows = packet.get('evidence') if isinstance(packet, dict) else None
    if (not isinstance(rows, list) or len(rows) != 2
            or any(not isinstance(row, dict) for row in rows)
            or [(row.get('id'), row.get('source')) for row in rows] != [
                ('listing_raw_audit', 'server_observation'),
                ('listing_raw_outcome', 'server_observation')]):
        raise RuntimeError('V62 original stored packet evidence identities mismatch')
    evidence, outcome = (row.get('content') for row in rows)
    if (packet.get('rubric', {}).get('objectiveId') != result['objectiveId']
            or packet.get('facts', {}).get('completed_browser_effect') is not True
            or not isinstance(evidence, dict) or evidence.get('operationId') != source_receipt.get('operationId')
            or evidence.get('originalSessionId') != original.get('source', {}).get('sessionId')
            or evidence.get('originalRequestId') != original.get('source', {}).get('requestId')
            or evidence.get('sourceDocumentSha256') != source_receipt.get('sourceDocumentSha256')
            or evidence.get('source') != source_receipt.get('source')
            or evidence.get('receipt') != dict(source_receipt, replayed=True)
            or evidence.get('browser', {}).get('targetEventExecuted') is not True
            or evidence.get('browser', {}).get('syntheticCookieOnly') is not True
            or evidence.get('browserEffectReceipt', {}).get('status') != 'completed'
            or ':listing-raw-browser:' not in str(evidence.get('browserEffectReceipt', {}).get('effectKey', ''))
            or not isinstance(outcome, dict) or outcome.get('kind') != 'saved_merchant_authored_html'
            or outcome.get('productId') != evidence.get('productId')
            or outcome.get('component') != evidence.get('component', {}).get('id')
            or outcome.get('markers') != evidence.get('browser', {}).get('markers')):
        raise RuntimeError('V62 original browser effect packet mismatch')
    sibling = value.get('listingRawBrowser', {}).get('sibling', {})
    foreign_source = sibling.get('foreignSource', {})
    foreign_value = foreign_source.get('value')
    if (foreign_source.get('status') != 200 or not isinstance(foreign_value, dict)
            or set(foreign_value) != {'operationId', 'status', 'scopeKey'}
            or foreign_value.get('operationId') != source_receipt.get('operationId')
            or foreign_value.get('status') != 'not_found'
            or not isinstance(foreign_value.get('scopeKey'), str)
            or not re.fullmatch(r'[a-f0-9]{64}', foreign_value['scopeKey'])
            or foreign_value['scopeKey'] == source_receipt.get('scopeKey')
            or sibling.get('foreignAssessment', {}).get('status') != 503
            or sibling.get('foreignAssessment', {}).get('value') != {'error': 'Role assistant unavailable'}):
        raise RuntimeError('V62 sibling closed source or assessment denial mismatch')
    reset = value.get('listingRawBrowser', {}).get('reset', {})
    for name, status, error in (
            ('oldSource', 401, 'Shop authentication required'),
            ('oldAssessment', 401, 'Shop authentication required'),
            ('renewedSource', 401, 'Shop session unavailable'),
            ('renewedAssessment', 503, 'Role assistant unavailable')):
        response = reset.get(name, {})
        if response.get('status') != status or response.get('value') != {'error': error}:
            raise RuntimeError('V62 retired authority phase-specific denial mismatch')
    judge_wire = [row for row in calls if row['kind'] == 'judge']
    proof_calls = proof.get('calls')
    if not isinstance(proof_calls, list) or len(proof_calls) != len(judge_wire):
        raise RuntimeError('V62 original configured Judge calls missing')
    for recorded, wire in zip(proof_calls, judge_wire):
        request = json.loads(wire['request'])
        canonical = json.dumps({'method': 'chat', 'input': request.get('messages'),
                                'schema': request.get('format')}, separators=(',', ':'), ensure_ascii=False)
        response = ''.join(json.loads(line).get('message', {}).get('content', '')
                           for line in wire['response'].strip().splitlines())
        if (recorded.get('provider') != 'ollama' or recorded.get('model') != OLLAMA_MODEL
                or recorded.get('requestSha256') != hashlib.sha256(canonical.encode()).hexdigest()
                or recorded.get('responseSha256') != hashlib.sha256(response.encode()).hexdigest()):
            raise RuntimeError('V62 configured Judge provenance does not match original wire')
    return hashlib.sha256(raw).hexdigest()


def merchant_review_receipt(target):
    target = Path(target)
    if target.is_symlink() or not target.is_file() or target.stat().st_uid != os.getuid() \
            or target.stat().st_mode & 0o777 != 0o600 or target.stat().st_size > 4096:
        raise RuntimeError('Private owned merchant review receipt required')
    receipt = json.loads(target.read_text())
    if (not isinstance(receipt, dict)
            or set(receipt) != set(MERCHANT_REVIEW_FLAGS) | {'scope', 'actorCalls', 'roleTurns', 'judgeCalls', 'errors'}
            or any(receipt.get(field) is not True for field in MERCHANT_REVIEW_FLAGS)
            or receipt.get('scope') != MERCHANT_REVIEW_SCOPE
            or type(receipt.get('roleTurns')) is not int or receipt['roleTurns'] != 8
            or type(receipt.get('actorCalls')) is not int or not 8 <= receipt['actorCalls'] <= 40
            or type(receipt.get('judgeCalls')) is not int or receipt['judgeCalls'] != 0
            or receipt.get('errors') != []):
        raise RuntimeError('Complete merchant review assertion and cleanup receipt required')
    return receipt


def q05_review_hidden_assessments(evidence, uid):
    """Exact no-award Q05 history: three bound hidden attempts from an empty ledger."""
    before, after = evidence.get('creditBefore'), evidence.get('creditAfter')
    if not isinstance(before, dict) or not isinstance(after, dict) \
            or set(before) != {'judgments', 'completions', 'contributions'} \
            or set(after) != set(before) \
            or any(type(value) is not int for value in (*before.values(), *after.values())) \
            or before != {'judgments': 0, 'completions': 0, 'contributions': 0} \
            or after != {'judgments': 3, 'completions': 0, 'contributions': 0}:
        return False
    witness = evidence.get('assessmentWitness')
    objectives = {'ss_loop_observation', 'ss_content_persist', 'ss_content_followed'}
    turn = evidence.get('turn')
    result = turn.get('result_json') if isinstance(turn, dict) else None
    metadata = result.get('taskMetadata') if isinstance(result, dict) else None
    batch = metadata.get('reviewBatch') if isinstance(metadata, dict) else None
    run_id = batch.get('runId') if isinstance(batch, dict) else None
    if not isinstance(witness, dict) or set(witness) != {
            'runId', 'rowCountAtLeast', 'truncated', 'rows', 'catalog'} \
            or witness.get('runId') != run_id or not isinstance(run_id, str) \
            or not re.fullmatch(uid, run_id) \
            or type(witness.get('rowCountAtLeast')) is not int or witness['rowCountAtLeast'] != 3 \
            or witness.get('truncated') is not False \
            or not isinstance(witness.get('rows'), list) or len(witness['rows']) != 3 \
            or not isinstance(witness.get('catalog'), list) or len(witness['catalog']) != 3:
        return False
    catalog = witness['catalog']
    if not all(isinstance(item, dict) and isinstance(item.get('objectiveId'), str)
               for item in catalog) \
            or {item['objectiveId'] for item in catalog} != objectives:
        return False
    for item in catalog:
        if not isinstance(item, dict) or set(item) != {
                'objectiveId', 'catalogActive', 'effectiveEnabled'} \
                or type(item['catalogActive']) is not bool \
                or type(item['effectiveEnabled']) is not bool \
                or (item['catalogActive'] and item['effectiveEnabled']):
            return False
    rows = witness['rows']
    if not all(isinstance(item, dict) and isinstance(item.get('objectiveId'), str)
               and isinstance(item.get('evaluationId'), str) for item in rows) \
            or {item['objectiveId'] for item in rows} != objectives \
            or len({item['evaluationId'] for item in rows}) != 3:
        return False
    keys = {'evaluationId', 'objectiveId', 'verdict', 'disposition', 'resultDigest',
            'resultVerdict', 'errorCode', 'modelEvaluated', 'providerPresent',
            'modelPresent', 'usagePresent', 'judgeObservationsState', 'judgeResultPresent',
            'principalBindingMatches', 'ownerScopeMatches', 'siblingScopeMatches'}
    for row in rows:
        if not isinstance(row, dict) or set(row) != keys \
                or not isinstance(row['evaluationId'], str) or not re.fullmatch(uid, row['evaluationId']) \
                or row['verdict'] != 'inconclusive' or row['resultVerdict'] != 'inconclusive' \
                or row['disposition'] != 'hidden' or not isinstance(row['resultDigest'], str) \
                or not re.fullmatch(r'[a-f0-9]{64}', row['resultDigest']) \
                or row['errorCode'] is not None or row['modelEvaluated'] is not None \
                or any(row[key] is not False for key in ('providerPresent', 'modelPresent',
                    'usagePresent', 'judgeResultPresent', 'siblingScopeMatches')) \
                or row['judgeObservationsState'] not in ('sql_null', 'json_null') \
                or any(row[key] is not True for key in ('principalBindingMatches', 'ownerScopeMatches')):
            return False
    return True


def q05_review_moderation_receipt(target):
    """Replay only the distinct, model-free Q05 rendered moderation facet."""
    def exact_json(actual, expected):
        # Python considers True == 1; the HTTP JSON DTO does not. Keep the
        # replay type-sensitive even when POST and saved GET agree on a bad value.
        try:
            return json.dumps(actual, sort_keys=True, separators=(',', ':'), allow_nan=False) == \
                json.dumps(expected, sort_keys=True, separators=(',', ':'), allow_nan=False)
        except (TypeError, ValueError):
            return False

    receipt = mail_inline_private_json(target, 1024 * 1024)
    required = set(Q05_REVIEW_FLAGS) | {'version', 'scope', 'actorCalls',
        'controlledActorCalls', 'controlledProviderCalls', 'actualModelCalls', 'judgeCalls', 'canonicalCredit',
        'chatTurns', 'errors', 'cleanupErrors', 'evidence'}
    if not isinstance(receipt, dict) or set(receipt) != required \
            or any(receipt.get(flag) is not True for flag in Q05_REVIEW_FLAGS) \
            or type(receipt.get('version')) is not int or receipt['version'] != 3 \
            or receipt.get('scope') != Q05_REVIEW_SCOPE \
            or any(type(receipt.get(key)) is not int or receipt[key] != expected
                   for key, expected in (('actorCalls', 0), ('controlledActorCalls', 3),
                       ('controlledProviderCalls', 3),
                       ('actualModelCalls', 0), ('judgeCalls', 0), ('canonicalCredit', 0),
                       ('chatTurns', 0))) \
            or receipt.get('errors') != [] or receipt.get('cleanupErrors') != []:
        raise RuntimeError('Exact controlled Q05 review moderation receipt required')
    evidence = receipt['evidence']
    if not isinstance(evidence, dict) or set(evidence) != {
            'scope', 'siblingScope', 'ownerTargetId', 'siblingTargetId',
            'ownerReviewTargetId', 'siblingReviewTargetId',
            'ownerReviewBirth', 'siblingReviewBirth',
            'ownerSceneMapping', 'siblingSceneMapping', 'siblingSceneMappingAfter',
            'siblingPersonaId', 'ownerProductBefore', 'siblingProductBefore',
            'siblingProductAfter', 'persona', 'personaSession', 'reviewId', 'requestId', 'physicalPost',
            'post', 'readback', 'beforeRows', 'afterRows', 'turn', 'effects', 'audits',
            'reset', 'staleBefore', 'staleAfter', 'siblingBefore', 'siblingAfter',
            'creditBefore', 'creditAfter', 'assessmentWitness', 'staleObservation'}:
        raise RuntimeError('Q05 durable evidence shape required')
    uid = r'[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}'
    request_id, review_id = evidence['requestId'], evidence['reviewId']
    if not isinstance(request_id, str) or not re.fullmatch(uid, request_id) \
            or type(review_id) is not int or review_id <= 0:
        raise RuntimeError('Q05 exact request/review identity required')
    scope, persona, session = evidence['scope'], evidence['persona'], evidence['personaSession']
    if not isinstance(scope, dict) or set(scope) != {'launchId', 'scenarioId', 'generation',
            'platformOwnerId', 'platformSessionId'} or not all(type(scope[key]) is int and scope[key] > 0
            for key in ('generation', 'platformOwnerId', 'platformSessionId')) \
            or any(not isinstance(scope[key], str) or not re.fullmatch(uid, scope[key])
                   for key in ('launchId', 'scenarioId')) \
            or not isinstance(persona, dict) or set(persona) != {'id', 'role'} \
            or type(persona['id']) is not int or persona['id'] <= 0 or persona['role'] != 'merchant' \
            or not isinstance(session, dict) or set(session) != {'sessionId', 'authorityVersion'} \
            or not isinstance(session['sessionId'], str) or not session['sessionId'] \
            or not isinstance(session['authorityVersion'], str) or not session['authorityVersion']:
        raise RuntimeError('Q05 original mounted merchant authority required')
    sibling_scope = evidence['siblingScope']
    owner_target, sibling_target = evidence['ownerTargetId'], evidence['siblingTargetId']
    owner_product = evidence['ownerProductBefore']
    sibling_product = evidence['siblingProductBefore']
    if not isinstance(sibling_scope, dict) or set(sibling_scope) != set(scope) \
            or type(sibling_scope.get('platformOwnerId')) is not int \
            or sibling_scope['platformOwnerId'] <= 0 \
            or sibling_scope['platformOwnerId'] == scope['platformOwnerId'] \
            or any(type(sibling_scope.get(key)) is not type(scope[key])
                   for key in scope) \
            or any(not isinstance(value, str) or not re.fullmatch(uid, value)
                   for value in (owner_target, sibling_target)) \
            or owner_target == sibling_target \
            or type(evidence['siblingPersonaId']) is not int \
            or evidence['siblingPersonaId'] <= 0 \
            or evidence['siblingPersonaId'] == persona['id'] \
            or not isinstance(owner_product, dict) or not isinstance(sibling_product, dict) \
            or owner_product.get('target_id') != owner_target \
            or sibling_product.get('target_id') != sibling_target \
            or type(owner_product.get('product_id')) is not int \
            or type(sibling_product.get('product_id')) is not int \
            or owner_product['product_id'] <= 0 or sibling_product['product_id'] <= 0 \
            or owner_product.get('retailer_id') != persona['id'] \
            or sibling_product.get('retailer_id') != evidence['siblingPersonaId'] \
            or owner_product.get('status') != 'active' \
            or sibling_product.get('status') != 'active' \
            or evidence['siblingProductAfter'] != sibling_product:
        raise RuntimeError('Q05 distinct owned composite products and sibling readback required')
    owner_review, sibling_review = evidence['ownerReviewTargetId'], evidence['siblingReviewTargetId']
    if any(not isinstance(value, str) or not re.fullmatch(uid, value)
           for value in (owner_review, sibling_review)) or owner_review == sibling_review:
        raise RuntimeError('Q05 distinct review targets required')
    for birth_key, review_target_id, owner_id in (
            ('ownerReviewBirth', owner_review, scope['platformOwnerId']),
            ('siblingReviewBirth', sibling_review, sibling_scope['platformOwnerId'])):
        birth = evidence[birth_key]
        if not isinstance(birth, dict) or set(birth) != set(scope) | {'targetId'} \
                or birth.get('targetId') != review_target_id \
                or birth.get('platformOwnerId') != owner_id \
                or any(type(birth.get(key)) is not type(scope[key]) for key in scope):
            raise RuntimeError('Q05 exact review birth identity required')
    for mapping_key, product_id, review_target_id, owner_id in (
            ('ownerSceneMapping', owner_target, owner_review, scope['platformOwnerId']),
            ('siblingSceneMapping', sibling_target, sibling_review,
             sibling_scope['platformOwnerId'])):
        mapping = evidence[mapping_key]
        if not isinstance(mapping, dict) or set(mapping) != {
                'scene_id', 'product_target_id', 'review_target_id',
                'original_platform_owner_id'} \
                or not isinstance(mapping['scene_id'], str) \
                or not re.fullmatch(uid, mapping['scene_id']) \
                or mapping['product_target_id'] != product_id \
                or mapping['review_target_id'] != review_target_id \
                or type(mapping['original_platform_owner_id']) is not int \
                or mapping['original_platform_owner_id'] != owner_id:
            raise RuntimeError('Q05 exact product-scene-to-review mapping required')
    if evidence['siblingSceneMappingAfter'] != evidence['siblingSceneMapping']:
        raise RuntimeError('Q05 sibling review scene mapping changed')
    post, physical, readback = (evidence[key] for key in ('post', 'physicalPost', 'readback'))
    route = '/api/secureshop/merchant/reviews/moderate-all'
    body = {'request_id': request_id, 'limit': 100,
            'recoveryScopeKey': post.get('body', {}).get('recoveryScopeKey') if isinstance(post, dict) else None}
    authority = {'scope': scope, 'persona': persona, 'session': session}
    if not isinstance(body['recoveryScopeKey'], str) or not re.fullmatch(r'[a-f0-9]{64}', body['recoveryScopeKey']) \
            or not isinstance(post, dict) or set(post) != {'method', 'path', 'query', 'body', 'status', 'value', 'authority'} \
            or post['method'] != 'POST' or post['path'] != route or post['status'] != 200 \
            or post['query'] != {} or post['body'] != body or post['authority'] != authority \
            or physical != {'method': 'POST', 'path': route, 'body': body, 'mainFrame': True}:
        raise RuntimeError('Q05 exact physical POST and production authority required')
    projection = post['value']
    if not isinstance(projection, dict) or set(projection) != {
            'ok', 'processed', 'decisions', 'stopReason', 'replayed', 'batch', 'modeCapability'} \
            or projection['ok'] is not True or type(projection['processed']) is not int \
            or projection['processed'] != 1 or projection['stopReason'] != 'end_turn' \
            or projection['replayed'] is not False \
            or not isinstance(projection['decisions'], list) or len(projection['decisions']) != 1 \
            or not exact_json(projection['decisions'][0], {
                'review_id': review_id, 'product_id': owner_product['product_id'],
                'applied_decision': 'approve', 'notes': None,
                'applied': {'ok': True, 'review_id': review_id}}) \
            or not exact_json(projection['batch'], {'requested': 100, 'considered': 1,
                'complete': True, 'continuationRequired': False}) \
            or not exact_json(projection['modeCapability'], {'version': 1, 'featureId': 'review',
                'policyVersion': 'product-feedback-enforced-decision-v1',
                'effectiveMode': 'vuln', 'scope': {'kind': 'launch_feature', 'id': 'review'}}):
        raise RuntimeError('Q05 actual one-review moderation projection required')
    get_path = f'/api/secureshop/merchant/reviews/moderation/{request_id}'
    if not isinstance(readback, dict) or set(readback) != {
            'method', 'path', 'query', 'status', 'value', 'authority'} \
            or readback.get('method') != 'GET' \
            or readback.get('path') != get_path or readback.get('status') != 200 \
            or readback.get('query') != {'limit': '100',
                'recoveryScopeKey': body['recoveryScopeKey']} \
            or readback.get('authority') != authority \
            or not isinstance(readback.get('value'), dict) \
            or set(readback['value']) != {'version', 'requestId', 'requestedLimit',
                'recoveryScopeKey', 'state', 'result'} \
            or type(readback['value'].get('version')) is not int or readback['value']['version'] != 1 \
            or readback['value'].get('requestId') != request_id \
            or type(readback['value'].get('requestedLimit')) is not int \
            or readback['value']['requestedLimit'] != 100 \
            or readback['value'].get('recoveryScopeKey') != body['recoveryScopeKey'] \
            or readback['value'].get('state') != 'completed' \
            or not exact_json(readback['value'].get('result'), projection):
        raise RuntimeError('Q05 exact same-request completed GET required')
    before, after = evidence['beforeRows'], evidence['afterRows']
    if not isinstance(before, list) or len(before) != 1 or not isinstance(after, list) or len(after) != 1 \
            or not isinstance(before[0], dict) or not isinstance(after[0], dict) \
            or str(before[0].get('id')) != str(review_id) or before[0].get('status') != 'pending' \
            or str(after[0].get('id')) != str(review_id) or after[0].get('status') != 'approved' \
            or str(before[0].get('product_id')) != str(owner_product['product_id']) \
            or after[0].get('moderator_kind') != 'auto' \
            or {**after[0], 'status': before[0]['status'],
                'moderator_kind': before[0].get('moderator_kind'),
                'moderator_notes': before[0].get('moderator_notes')} != before[0]:
        raise RuntimeError('Q05 one owned durable review transition required')
    turn, effects, audits = (evidence[key] for key in ('turn', 'effects', 'audits'))
    if not isinstance(turn, dict) or turn.get('request_id') != request_id \
            or turn.get('status') != 'completed' or not isinstance(turn.get('result_json'), dict):
        raise RuntimeError('Q05 completed turn missing')
    result = turn['result_json']
    try:
        run_id = result['taskMetadata']['reviewBatch']['runId']
        hops = result['hops']
        audit = json.loads(audits[0]['params_json'])['receipt']
    except (KeyError, IndexError, TypeError, ValueError) as error:
        raise RuntimeError('Q05 graph/audit binding unavailable') from error
    if not isinstance(run_id, str) or not re.fullmatch(uid, run_id) \
            or not isinstance(hops, list) or len(hops) != 2 \
            or [hop.get('tool') for hop in hops] != ['review-moderator.moderate_pending', 'review-moderator.approve'] \
            or hops[1].get('params', {}).get('review_id') != review_id \
            or not isinstance(effects, list) or len(effects) != 2 \
            or len({row.get('effect_key') for row in effects}) != 2 \
            or any(row.get('run_id') != run_id or row.get('status') != 'completed' for row in effects) \
            or not isinstance(audits, list) or len(audits) != 1 \
            or audit.get('runId') != run_id or audit.get('reviewId') != review_id \
            or audit.get('applied') is not True or audit.get('resultStatus') != 'approved' \
            or audit.get('scope') != evidence['ownerReviewBirth'] \
            or audits[0].get('launch_id') != scope['launchId'] \
            or audits[0].get('scenario_id') != scope['scenarioId'] \
            or not isinstance(audits[0].get('generation'), str) \
            or audits[0]['generation'] != str(scope['generation']) \
            or audits[0].get('original_platform_owner_id') != scope['platformOwnerId'] \
            or audits[0].get('original_platform_session_id') != scope['platformSessionId'] \
            or audit.get('actor', {}).get('id') != persona['id'] \
            or audit['actor'].get('role') != 'merchant' \
            or audit['actor'].get('personaSessionId') != session['sessionId']:
        raise RuntimeError('Q05 durable graph effect and audit binding required')
    stale = evidence['staleObservation']
    if not isinstance(stale, dict) or set(stale) != {'disabled', 'responses', 'providerCallsBefore',
            'providerCallsAfter', 'postsBefore', 'postsAfter'} \
            or type(stale['disabled']) is not bool or stale['postsBefore'] != 1 or stale['postsAfter'] != 1 \
            or stale['providerCallsBefore'] != 3 or stale['providerCallsAfter'] != 3 \
            or not isinstance(stale['responses'], list) \
            or any(row.get('method') == 'POST' for row in stale['responses']) \
            or (not stale['disabled'] and not any(row.get('method') == 'GET' and row.get('status') == 401
                                                  for row in stale['responses'])) \
            or evidence['staleAfter'] != evidence['staleBefore'] \
            or not isinstance(evidence['siblingBefore'], list) or not evidence['siblingBefore'] \
            or evidence['siblingAfter'] != evidence['siblingBefore'] \
            or not any(type(row) is dict and row.get('product_id') == sibling_product['product_id']
                       for row in evidence['siblingBefore']) \
            or not q05_review_hidden_assessments(evidence, uid) \
            or not isinstance(evidence['reset'], dict) \
            or not isinstance(evidence['reset'].get('resetId'), str):
        raise RuntimeError('Q05 stale authority, sibling and zero-credit fence required')
    return receipt


def q05_review_build_sha256(pins):
    """Match the existing Q05 JS buildInventory over the pinned build closure."""
    prefix = 'client/build/'
    entries = {name[len(prefix):]: value for name, value in pins['sourcePins'].items()
               if name.startswith(prefix)}
    if 'index.html' not in entries or not entries \
            or any(not re.fullmatch(r'[0-9a-f]{64}', value) for value in entries.values()):
        raise RuntimeError('Exact Q05 existing build inventory required')
    canonical = json.dumps(dict(sorted(entries.items())), separators=(',', ':'),
                           ensure_ascii=False).encode()
    return hashlib.sha256(canonical).hexdigest()


def q05_review_controlled_provider_count(validated_receipt):
    """Only a validated successful facet can claim three controlled calls."""
    return None if validated_receipt is None else validated_receipt['controlledActorCalls']


class Q05ReviewBrowserOwner:
    """One direct Node grant and independently captured browser birth for Q05 only."""

    COHORT = 'q05-review-moderation-browser'
    TEST = Q05_REVIEW_TEST
    PREFIX = 'SECURESHOP_Q05_REVIEW_MODERATION_'
    RECORD = 'q05-review-moderation-browser-birth.json'
    ACK = 'q05-review-moderation-browser-ack.json'
    RECEIPT = 'q05-review-moderation-rendered.json'
    KIND = 'q05_review_moderation_browser'
    PROFILE = 'owasp-ai-goat-q05-review-'

    def __init__(self, original, source, evidence, runtime, node, browser,
                 browser_sha256, build_sha256, snapshot_sha256, api=None,
                 ownership=None):
        self.original, self.source, self.evidence, self.runtime = original, source, evidence, runtime
        self.node, self.browser, self.browser_sha256 = node, browser, browser_sha256
        self.build_sha256, self.snapshot_sha256 = build_sha256, snapshot_sha256
        self.api, self.ownership = api, ownership
        self.captured = self.error = None
        self.browser_retired = self.profile_removed = False
        self.worker_pid = None
        self.stopped = self.watcher = None

    def _modules(self):
        if self.ownership is None:
            name = 'q05_review_independent_browser_ownership'
            spec = importlib.util.spec_from_file_location(
                name, self.source / 'tests/postgres/run-secureshop-audit-collection-browser.py')
            self.ownership = importlib.util.module_from_spec(spec)
            spec.loader.exec_module(self.ownership)
            self.ownership.PROFILE_PREFIX = self.PROFILE
        if self.api is None:
            self.api = self.ownership._browser_modules()[0]()
        return self.ownership, self.api

    @staticmethod
    def _publish_ack(ack_path, ack):
        """Publish one complete private ACK; never expose partial JSON or replace one."""
        stage = ack_path.with_name(ack_path.name + '.staged-' + os.urandom(8).hex())
        flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, 'O_NOFOLLOW', 0)
        created = None
        try:
            fd = os.open(stage, flags, 0o600)
            identity = os.fstat(fd)
            created = (identity.st_dev, identity.st_ino)
            with os.fdopen(fd, 'w') as output:
                json.dump(ack, output, sort_keys=True, separators=(',', ':'))
                output.write('\n'); output.flush(); os.fsync(output.fileno())
            os.link(stage, ack_path, follow_symlinks=False)
            directory = os.open(ack_path.parent, os.O_RDONLY | getattr(os, 'O_DIRECTORY', 0))
            try:
                os.fsync(directory)
            finally:
                os.close(directory)
        finally:
            if created is not None:
                current = stage.lstat()
                if (current.st_dev, current.st_ino) != created:
                    raise RuntimeError('Q05 ACK staging identity changed')
                stage.unlink()

    def _watch(self, child, birth, stopped):
        ownership, api = self._modules()
        _, _, _, read_record, _ = ownership._browser_modules()
        record_path = self.evidence / self.RECORD
        ack_path = self.evidence / self.ACK
        until = time.monotonic() + 60
        try:
            while not stopped.is_set() and time.monotonic() < until:
                if not record_path.exists() and not record_path.is_symlink():
                    stopped.wait(.025)
                    continue
                info = record_path.lstat()
                if not stat.S_ISREG(info.st_mode) or info.st_nlink != 1:
                    raise RuntimeError('Exclusive Q05 birth record required')
                records = read_record(self.evidence, record_path.name,
                    self.KIND, self.browser, self.browser_sha256,
                    child.pid, parent_pid=child.pid, require_all=True,
                    allow_browser_session=True)
                captured = ownership.capture_live_v36(records[0], birth, self.runtime, api=api)
                profile = Path(captured.profile)
                if profile.parent != self.runtime / 'tmp' \
                        or not profile.name.startswith(self.PROFILE) \
                        or profile.resolve() != profile:
                    raise RuntimeError('Exact Q05 owned profile required')
                identity = profile.lstat()
                if not stat.S_ISDIR(identity.st_mode) or identity.st_uid != os.getuid() \
                        or stat.S_IMODE(identity.st_mode) != 0o700:
                    raise RuntimeError('Private Q05 captured profile required')
                captured.q05_profile_identity = (identity.st_dev, identity.st_ino)
                self.captured = captured
                record_bytes = record_path.read_bytes()
                after = record_path.lstat()
                if (info.st_dev, info.st_ino, info.st_size, info.st_mtime_ns) != \
                        (after.st_dev, after.st_ino, after.st_size, after.st_mtime_ns) \
                        or len(record_bytes) != info.st_size:
                    raise RuntimeError('Q05 browser record changed during capture')
                ack = dict(schemaVersion=1, recordSha256=hashlib.sha256(record_bytes).hexdigest(),
                    parentPid=child.pid, browserPid=records[0]['pid'], profile=str(profile))
                self._publish_ack(ack_path, ack)
                return
            if not stopped.is_set():
                raise RuntimeError('Q05 browser live birth timed out')
        except BaseException as error:
            self.error = error

    def _retire(self):
        if self.captured is None:
            return
        ownership, api = self._modules()
        ownership.retire_live_v36(self.captured, api=api)
        _, _, _, _, absent = ownership._browser_modules()
        absent([self.captured.record])
        self.browser_retired = True
        profile = Path(self.captured.profile)
        identity = profile.lstat()
        if not stat.S_ISDIR(identity.st_mode) or identity.st_uid != os.getuid() \
                or stat.S_IMODE(identity.st_mode) != 0o700 \
                or (identity.st_dev, identity.st_ino) != self.captured.q05_profile_identity \
                or profile.resolve() != profile:
            raise RuntimeError('Q05 captured profile changed before retirement')
        shutil.rmtree(profile)
        if profile.exists() or profile.is_symlink():
            raise RuntimeError('Q05 retired profile remains')
        self.profile_removed = True

    def finish_after_worker_retired(self):
        """Only the already reaped direct worker permits browser/profile retirement."""
        if self.stopped is not None:
            self.stopped.set()
        if self.watcher is not None:
            self.watcher.join(timeout=2)
            if self.watcher.is_alive():
                self.error = self.error or RuntimeError('Q05 browser watcher remains')
        try:
            self._retire()
        except BaseException as error:
            self.error = self.error or error
        if self.error is not None:
            raise self.error

    def __call__(self, command, *args, **kwargs):
        if list(command) != [self.node, '--test', '--test-isolation=none',
                             '--test-reporter=tap', '--test-concurrency=1', self.TEST] \
                or kwargs.get('start_new_session') is not True or kwargs.get('pass_fds'):
            raise RuntimeError('Exclusive direct Q05 browser worker required')
        env = dict(kwargs['env'])
        prefix = self.PREFIX
        if prefix + 'ADMISSION_FD' in env:
            raise RuntimeError('Nested Q05 descriptor forbidden')
        read_fd, write_fd = os.pipe()
        child = None
        stopped = watcher = None
        try:
            env[prefix + 'ADMISSION_FD'] = str(read_fd)
            child = self.original(command, *args, **{**kwargs, 'env': env,
                'close_fds': True, 'pass_fds': (read_fd,)})
            self.worker_pid = child.pid
            os.close(read_fd); read_fd = None
            ownership, api = self._modules()
            zombie = ownership._browser_modules()[1]
            node = api.identity(child.pid)
            if node is None or node.ppid != os.getpid() or node.uid != os.getuid() \
                    or node.ruid != os.getuid() or node.pgid != child.pid \
                    or os.getsid(child.pid) != child.pid or node.status == zombie:
                raise RuntimeError('Q05 worker live birth unavailable before grant')
            birth = (node.start_sec, node.start_usec)
            grant = dict(version=1, cohort=self.COHORT,
                launcherPid=os.getpid(), workerPid=child.pid, nonce=os.urandom(32).hex(),
                workspace=str(self.source), evidencePath=str(self.evidence / self.RECEIPT),
                buildSha256=self.build_sha256, snapshotSha256=self.snapshot_sha256,
                outerSandbox='repository-only', chromium=self.browser,
                chromiumSha256=self.browser_sha256)
            stopped = threading.Event()
            watcher = threading.Thread(target=self._watch, args=(child, birth, stopped),
                                       name='q05-review-browser-birth', daemon=True)
            self.stopped, self.watcher = stopped, watcher
            watcher.start()
            payload = json.dumps(grant, separators=(',', ':')).encode()
            if len(payload) > 8192 or os.write(write_fd, payload) != len(payload):
                raise RuntimeError('Complete bounded Q05 FIFO grant required')
            os.close(write_fd); write_fd = None
            original_wait = child.wait
            def wait(*wait_args, **wait_kwargs):
                try:
                    code = original_wait(*wait_args, **wait_kwargs)
                finally:
                    child.wait = original_wait
                self.finish_after_worker_retired()
                return code
            child.wait = wait
            return child
        except BaseException as error:
            if stopped is not None:
                stopped.set()
            if watcher is not None:
                watcher.join(timeout=2)
            if child is None:
                raise
            self.error = self.error or error
            original_wait = child.wait
            def fail_first_wait(*_args, **_kwargs):
                child.wait = original_wait
                raise self.error
            child.wait = fail_first_wait
            return child
        finally:
            for descriptor in (read_fd, write_fd):
                if descriptor is not None:
                    os.close(descriptor)


class AdminResetBrowserOwner(Q05ReviewBrowserOwner):
    """Closed reset-only binding of the existing browser lifetime owner."""

    COHORT = 'admin-password-reset-chat-browser'
    TEST = ADMIN_PASSWORD_RESET_CHAT_TEST
    PREFIX = 'SECURESHOP_ADMIN_RESET_BROWSER_'
    RECORD = 'admin-reset-browser-birth.json'
    ACK = 'admin-reset-browser-ack.json'
    RECEIPT = 'admin-password-reset-chat-browser.json'
    KIND = 'admin_reset_browser'
    PROFILE = 'owasp-ai-goat-role-admin-reset-'

    def _retire(self):
        # run_node and the outer finally may both finalize a failed worker.
        # Preserve the original failure, without re-signalling a retired birth
        # or touching a replacement profile at the old path.
        if self.profile_removed:
            profile = Path(self.captured.profile)
            if profile.exists() or profile.is_symlink():
                raise RuntimeError('Retired administrator reset profile path reappeared')
            return
        super()._retire()


def admin_reset_validate_pins(source):
    required = {ADMIN_PASSWORD_RESET_CHAT_TEST,
        'tests/fixtures/secureshopAdminResetBrowserAdmission.js',
        'tests/secureshopAdminResetBrowserAdmission.test.js'}
    if set(ADMIN_RESET_BROWSER_PINS) != required:
        raise RuntimeError('Closed administrator reset source pin set required')
    for name, expected in ADMIN_RESET_BROWSER_PINS.items():
        path = source / name
        if path.is_symlink() or path.resolve() != path \
                or not re.fullmatch(r'[0-9a-f]{64}', expected) or digest(path) != expected:
            raise RuntimeError('Frozen administrator reset source required: ' + name)


def admin_reset_browser_environment(source, evidence, runtime, browser, browser_sha256, pins):
    """Exact reset-only grant inputs; no ambient opt-in or changed scenario."""
    prefix = AdminResetBrowserOwner.PREFIX
    return {
        prefix + 'TEST_NO_SANDBOX': '1',
        prefix + 'BROWSER_RECORD_PATH': str(evidence / AdminResetBrowserOwner.RECORD),
        prefix + 'BROWSER_ACK_PATH': str(evidence / AdminResetBrowserOwner.ACK),
        prefix + 'BROWSER_SHA256': browser_sha256,
        prefix + 'BUILD_SHA256': q05_review_build_sha256(pins),
        prefix + 'SNAPSHOT_SHA256': digest(evidence / 'source-before.json'),
        'SECURESHOP_BOUND_BROWSER_BIRTH_SCRIPT': str(source / 'tests/postgres/secureshop_darwin_browser_birth.py'),
        'SECURESHOP_BOUND_BROWSER_BIRTH_PYTHON': str(Path(sys.executable).resolve()),
        'MAC_CHROMIUM_TMPDIR': str(runtime / 'tmp'),
    }


def user_lookup_receipt(target):
    receipt = mail_inline_private_json(target, 4096)
    if (not isinstance(receipt,dict)
            or set(receipt) != set(USER_LOOKUP_FLAGS) | {'scope','catalogAdmission','actorCalls','roleTurns','judgeCalls','genuineCredit','errors'}
            or any(receipt.get(field) is not True for field in USER_LOOKUP_FLAGS)
            or receipt.get('scope') != USER_LOOKUP_SCOPE
            or any(type(receipt.get(key)) is not int or receipt[key] != expected
                   for key,expected in [('actorCalls',4),('roleTurns',2),('judgeCalls',4),('genuineCredit',1)])
            or receipt.get('errors') != []):
        raise RuntimeError('Complete exact bounded user lookup receipt required')
    admission=receipt.get('catalogAdmission')
    if (not isinstance(admission,dict)
            or type(admission.get('fixtureLocalCandidateAdmission')) is not bool
            or type(admission.get('productionDefaultEnabled')) is not bool
            or admission != {'objectiveId':'ss_user_lookup_sensitive_disclosure',
                'fixtureLocalCandidateAdmission':admission['fixtureLocalCandidateAdmission'],
                'productionQualification':'pending' if admission['fixtureLocalCandidateAdmission'] else 'native-browser-judge',
                'productionDefaultEnabled':False}):
        raise RuntimeError('Closed truthful lookup catalog admission required')
    return receipt


def user_lookup_capture(target, node, source, model_digest):
    value=mail_inline_private_json(target,16*1024*1024)
    if (not isinstance(value,dict) or value.get('version') != 1
            or value.get('modelIdentity') != {'model':OLLAMA_MODEL,'digest':model_digest,'maximumPhysicalCalls':8}
            or value.get('cleanup') != {'fixtureCleaned':True,'errors':[]}):
        raise RuntimeError('User lookup original model/cleanup identity required')
    script="""const fs=require('node:fs');const value=JSON.parse(fs.readFileSync(process.argv[1],'utf8'));
    const {binding,personaSession,target}=value.subject;
    require(process.argv[2]).assertUserLookupOriginalCapture({subject:{binding,personaSession,target},cases:value.cases,canonicalJudge:value.canonicalJudge,wire:value.wire});"""
    subprocess.run([str(node),'-e',script,str(target),str(source / USER_LOOKUP_HELPER)],cwd=source,check=True,capture_output=True,timeout=30)
    return digest(target)


def user_lookup_benign_receipt(target):
    receipt = mail_inline_private_json(target, 4096)
    expected = set(USER_LOOKUP_FLAGS) | {'scope', 'catalogAdmission', 'actorCalls',
        'roleTurns', 'judgeCalls', 'genuineCredit', 'errors', 'actorNegativeCapture',
        'independentJudgeCalibration'}
    if not isinstance(receipt, dict) or set(receipt) != expected:
        raise RuntimeError('Exact benign user lookup receipt required')
    if (receipt.get('scope') != USER_LOOKUP_BENIGN_SCOPE
            or any(receipt.get(flag) is not True for flag in USER_LOOKUP_FLAGS
                   if flag not in ('fourIndependentJudgeCriteria', 'canonicalTenantCredit'))
            or receipt.get('fourIndependentJudgeCriteria') is not False
            or receipt.get('canonicalTenantCredit') is not False
            or receipt.get('actorNegativeCapture') is not True
            or receipt.get('independentJudgeCalibration') is not False
            or any(type(receipt.get(key)) is not int or receipt[key] != expected_value
                   for key, expected_value in [('actorCalls', 4), ('roleTurns', 2),
                                               ('judgeCalls', 0), ('genuineCredit', 0)])
            or receipt.get('errors') != []):
        raise RuntimeError('Benign user lookup requires four actor calls, zero Judge and no credit')
    admission = receipt.get('catalogAdmission')
    if (not isinstance(admission, dict)
            or type(admission.get('fixtureLocalCandidateAdmission')) is not bool
            or type(admission.get('productionDefaultEnabled')) is not bool
            or admission != {'objectiveId': 'ss_user_lookup_sensitive_disclosure',
                'fixtureLocalCandidateAdmission': admission['fixtureLocalCandidateAdmission'],
                'productionQualification': 'pending' if admission['fixtureLocalCandidateAdmission'] else 'native-browser-judge',
                'productionDefaultEnabled': False}):
        raise RuntimeError('Closed truthful benign lookup catalog admission required')
    return receipt


def user_lookup_benign_capture(target, node, source, model_digest):
    value = mail_inline_private_json(target, 16 * 1024 * 1024)
    if (not isinstance(value, dict) or value.get('version') != 1
            or value.get('captureVariant') != USER_LOOKUP_BENIGN_VERSION
            or value.get('independentJudgeCalibration') is not False
            or value.get('modelIdentity') != {'model': OLLAMA_MODEL, 'digest': model_digest,
                                             'maximumPhysicalCalls': 4}
            or value.get('cleanup') != {'fixtureCleaned': True, 'errors': []}):
        raise RuntimeError('Benign lookup original model, variant and cleanup identity required')
    script = """const fs=require('node:fs');const value=JSON.parse(fs.readFileSync(process.argv[1],'utf8'));
    require(process.argv[2]).assertCapture(value);"""
    subprocess.run([str(node), '-e', script, str(target), str(source / USER_LOOKUP_BENIGN_HELPER)],
                   cwd=source, check=True, capture_output=True, timeout=30)
    return digest(target)


def admin_user_chat_receipt(target):
    target = Path(target)
    if target.is_symlink() or not target.is_file() or target.stat().st_uid != os.getuid() \
            or target.stat().st_mode & 0o777 != 0o600 or target.stat().st_size > 4096:
        raise RuntimeError('Private owned administrator user-chat receipt required')
    receipt = json.loads(target.read_text())
    if (not isinstance(receipt, dict)
            or set(receipt) != set(ADMIN_USER_CHAT_FLAGS) | {'scope', 'actorCalls', 'roleTurns', 'judgeCalls', 'errors'}
            or any(receipt.get(field) is not True for field in ADMIN_USER_CHAT_FLAGS)
            or receipt.get('scope') != ADMIN_USER_CHAT_SCOPE
            or type(receipt.get('roleTurns')) is not int or receipt['roleTurns'] != 4
            or type(receipt.get('actorCalls')) is not int or not 4 <= receipt['actorCalls'] <= 20
            or type(receipt.get('judgeCalls')) is not int or receipt['judgeCalls'] != 0
            or receipt.get('errors') != []):
        raise RuntimeError('Complete administrator user-chat assertion and cleanup receipt required')
    return receipt



