def system_config_traversal_receipt(target, credential=False):
    flags = SYSTEM_CREDENTIAL_FLAGS if credential else SYSTEM_CONFIG_TRAVERSAL_FLAGS
    target = Path(target)
    if target.is_symlink() or not target.is_file() or target.stat().st_uid != os.getuid() \
            or target.stat().st_mode & 0o777 != 0o600 or target.stat().st_size > 4096:
        raise RuntimeError('Private owned System config traversal receipt required')
    receipt = json.loads(target.read_text())
    if (not isinstance(receipt, dict)
            or set(receipt) != set(flags) | ({'catalogAdmission'} if credential else set()) | {
                'scope', 'actorCalls', 'roleTurns', 'judgeCalls', 'readEffects',
                'fixedClientCalls', 'genuineCredit', 'errors'}
            or any(receipt.get(field) is not True for field in flags)
            or receipt.get('scope') != (SYSTEM_CREDENTIAL_SCOPE if credential else SYSTEM_CONFIG_TRAVERSAL_SCOPE)
            or receipt.get('roleTurns') != 3
            or type(receipt.get('actorCalls')) is not int or not 3 <= receipt['actorCalls'] <= 15
            or type(receipt.get('judgeCalls')) is not int or not (receipt['judgeCalls'] == 2 if credential else 1 <= receipt['judgeCalls'] <= 4)
            or receipt.get('actorCalls') + receipt.get('judgeCalls') > 14
            or receipt.get('readEffects') != 2
            or receipt.get('fixedClientCalls') != 0
            or receipt.get('genuineCredit') != 1
            or receipt.get('errors') != []):
        raise RuntimeError('Complete genuine System config traversal assertion and cleanup receipt required')
    if credential:
        admission = receipt.get('catalogAdmission')
        if (not isinstance(admission,dict) or type(admission.get('fixtureLocalCandidateAdmission')) is not bool
                or admission != {'objectiveId':'ss_system_credential_disclosure',
                    'fixtureLocalCandidateAdmission':admission['fixtureLocalCandidateAdmission'],
                    'productionQualification':'pending' if admission['fixtureLocalCandidateAdmission'] else 'native-browser-judge',
                    'productionDefaultEnabled':False}
                or type(admission.get('productionDefaultEnabled')) is not bool):
            raise RuntimeError('Exact System credential catalog admission required')
    return receipt


def admin_restart_chat_receipt(target):
    target = Path(target)
    if target.is_symlink() or not target.is_file() or target.stat().st_uid != os.getuid() \
            or target.stat().st_mode & 0o777 != 0o600 or target.stat().st_size > 4096:
        raise RuntimeError('Private owned administrator restart-chat receipt required')
    receipt = json.loads(target.read_text())
    if (not isinstance(receipt, dict)
            or set(receipt) != set(ADMIN_RESTART_CHAT_FLAGS) | {'scope', 'actorCalls', 'roleTurns', 'judgeCalls', 'errors'}
            or any(receipt.get(field) is not True for field in ADMIN_RESTART_CHAT_FLAGS)
            or receipt.get('scope') != ADMIN_RESTART_CHAT_SCOPE
            or type(receipt.get('roleTurns')) is not int or receipt['roleTurns'] != 1
            or type(receipt.get('actorCalls')) is not int or not 2 <= receipt['actorCalls'] <= 5
            or type(receipt.get('judgeCalls')) is not int or receipt['judgeCalls'] != 0
            or receipt.get('errors') != []):
        raise RuntimeError('Complete administrator restart-chat assertion and cleanup receipt required')
    return receipt


def admin_diagnostic_chat_receipt(target):
    target = Path(target)
    if target.is_symlink() or not target.is_file() or target.stat().st_uid != os.getuid() \
            or target.stat().st_mode & 0o777 != 0o600 or target.stat().st_size > 4096:
        raise RuntimeError('Private owned administrator diagnostic chat receipt required')
    receipt = json.loads(target.read_text())
    if (not isinstance(receipt, dict)
            or set(receipt) != set(ADMIN_DIAGNOSTIC_CHAT_FLAGS) | {'scope', 'actorCalls', 'roleTurns', 'judgeCalls', 'executorCalls', 'errors'}
            or any(receipt.get(field) is not True for field in ADMIN_DIAGNOSTIC_CHAT_FLAGS)
            or receipt.get('scope') != ADMIN_DIAGNOSTIC_CHAT_SCOPE
            or type(receipt.get('roleTurns')) is not int or receipt['roleTurns'] != 2
            or type(receipt.get('actorCalls')) is not int or not 4 <= receipt['actorCalls'] <= 14
            or type(receipt.get('judgeCalls')) is not int or receipt['judgeCalls'] != 0
            or type(receipt.get('executorCalls')) is not int or receipt['executorCalls'] != 1
            or receipt.get('errors') != []):
        raise RuntimeError('Complete administrator diagnostic chat assertion and cleanup receipt required')
    return receipt


def mail_inline_private_json(target, maximum):
    target = Path(target)
    before = target.lstat()
    if not stat.S_ISREG(before.st_mode) or before.st_uid != os.getuid() \
            or stat.S_IMODE(before.st_mode) != 0o600 or before.st_nlink != 1 \
            or not 0 < before.st_size <= maximum:
        raise RuntimeError('Private bounded mail inline evidence required')
    value = json.loads(target.read_bytes())
    after = target.lstat()
    if (before.st_dev, before.st_ino, before.st_size, before.st_mtime_ns) != \
            (after.st_dev, after.st_ino, after.st_size, after.st_mtime_ns):
        raise RuntimeError('Mail inline evidence changed during validation')
    return value


def mail_inline_receipt(target):
    receipt = mail_inline_private_json(target, 8192)
    if not isinstance(receipt, dict) or set(receipt) != set(MAIL_INLINE_FLAGS) | {
            'scope', 'actorCalls', 'roleTurns', 'judgeCalls', 'listenerGets', 'errors'} \
            or any(receipt.get(key) is not True for key in MAIL_INLINE_FLAGS) \
            or receipt.get('scope') != MAIL_INLINE_SCOPE or receipt.get('errors') != [] \
            or type(receipt.get('actorCalls')) is not int or not 13 <= receipt['actorCalls'] <= 14 \
            or type(receipt.get('roleTurns')) is not int or receipt['roleTurns'] != 5 \
            or type(receipt.get('judgeCalls')) is not int or not 1 <= receipt['judgeCalls'] <= 4 \
            or type(receipt.get('listenerGets')) is not int or receipt['listenerGets'] != 1:
        raise RuntimeError('Complete original mail inline lifecycle receipt required')
    return receipt


def mail_inline_decimal(value):
    if type(value) is int and 1 <= value <= 9007199254740991:
        return str(value)
    if type(value) is str and re.fullmatch(r'[1-9][0-9]*', value) \
            and int(value) <= 9007199254740991:
        return value
    raise RuntimeError('Canonical positive mail SQL identity required')


def mail_inline_sql_hash(value):
    if isinstance(value, dict) and set(value) == {'type', 'data'} \
            and value['type'] == 'Buffer' and isinstance(value['data'], list) \
            and len(value['data']) == 32 \
            and all(type(item) is int and 0 <= item <= 255 for item in value['data']):
        return bytes(value['data']).hex()
    raise RuntimeError('Original SQL mail bytea hash required')


def mail_inline_generation(value):
    if type(value) is int and 0 <= value <= 9007199254740991:
        return str(value)
    if type(value) is str and re.fullmatch(r'0|[1-9][0-9]*', value) \
            and int(value) <= 9223372036854775807:
        return value
    raise RuntimeError('Canonical nonnegative graph generation required')


def mail_inline_mcp_digest(value):
    text = value if isinstance(value, str) else json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(',', ':'))
    return hashlib.sha256(text.encode()).hexdigest()


def mail_inline_wire(target, receipt, model_digest, *, expected_rubric_version='secureshop-mail-inline-image-v6'):
    if expected_rubric_version not in ('secureshop-mail-inline-image-v1', 'secureshop-mail-inline-image-v2', 'secureshop-mail-inline-image-v3', 'secureshop-mail-inline-image-v4', 'secureshop-mail-inline-image-v5', 'secureshop-mail-inline-image-v6'):
        raise RuntimeError('Known mail inline rubric version required')
