        if call.get('index') != expected_index or call.get('model') != OLLAMA_MODEL \
                or call.get('status') != 200 or call.get('error') \
                or call.get('responseComplete') is not True or call.get('responseCaptureTruncated') is not False \
                or call.get('terminalReason') != 'end' or call.get('responseObservedBytes') != call.get('responseBytes'):
            raise RuntimeError('Original mail inline model HTTP incomplete')
