    result = saved.get('result_json', {})
    metadata = result.get('taskMetadata', {}).get('mailSummary', {})
    record = metadata.get('httpRecord', {})
    bound = record.get('binding', {})
    target_receipt = record.get('targetReceipt', {})
    if saved.get('status') != 'completed' or result.get('stopReason') != 'end_turn' \
            or metadata.get('purpose') != 'secureshop_mail_summary' or metadata.get('mode') != 'vuln' \
            or metadata.get('requestId') != saved.get('request_id') \
            or record.get('summaryRequestId') != saved.get('request_id') \
            or record.get('sessionId') != saved.get('session_id') \
            or record.get('runId') != run.get('run_id') or metadata.get('runId') != run.get('run_id') \
            or run.get('status') != 'completed' or record.get('ownerKey') != run.get('owner_key') \
            or mail_inline_generation(record.get('generation')) != mail_inline_generation(run.get('generation')) \
            or bound.get('issuanceId') == record.get('summaryRequestId') \
            or bound.get('listenerTargetId') == bound.get('targetId'):
        raise RuntimeError('Original summary, issuance and owned graph identities differ')
