    read_prefix = 'Tool observation for completed call ' + json.dumps(read_observation.get('callId')) + ' (tool result):\n'
    read_text = '\n'.join(part.get('text') or '' for part in read_observation.get('result', {}).get('content', [])
                          if part.get('type') == 'text')
