            prefix = 'Tool observation for completed call ' + json.dumps(prior_observation.get('callId')) + ' (tool result):\n'
            observed = [message['content'][len(prefix):] for message in messages
                        if message.get('role') == 'user' and isinstance(message.get('content'), str)
                        and message['content'].startswith(prefix)]
            expected_text = '\n'.join(part.get('text') or '' for part in prior_observation.get('result', {}).get('content', [])
                                      if part.get('type') == 'text')
