        model = observed.get('metadata', {})
        if observed.get('transport') != 'returned' or observed.get('disposition') not in ('accepted','rejected') \
                or observed.get('request', {}).get('method') != 'chat' \
                or observed['request'].get('input') != request.get('messages') \
                or observed['request'].get('schema') != request.get('format') \
                or observed.get('response') != response or observed.get('responseSha256') != hashlib.sha256(response.encode()).hexdigest() \
                or model.get('provider') != 'ollama' or model.get('model') != OLLAMA_MODEL \
                or model.get('mocked') is not False or model.get('fallback') is not False:
            raise RuntimeError('Configured mail Judge differs from original HTTP')
