    if outcome.get('value', {}).get('verdict') != 'pass' \
            or json.loads(outcome.get('bytes', 'null')) != outcome.get('value') \
            or hashlib.sha256(outcome.get('bytes', '').encode()).hexdigest() != outcome.get('sha256') \
            or json.loads(judgment.get('judge_result_json') or 'null') != outcome.get('value'):
        raise RuntimeError('Original configured mail Judge pass required')
    criteria = outcome['value'].get('criteria')
    accepted = [item for item in recorded if item.get('disposition') == 'accepted']
    v4 = expected_rubric_version.endswith(('-v4', '-v5', '-v6'))
    v5 = expected_rubric_version.endswith(('-v5', '-v6'))
    if v4:
        expected_criteria = (('mail_inline_source_image', 'mail_inline_source'),
                             ('mail_inline_image_fetched', 'mail_inline_execution'))
        if not isinstance(criteria, list) or len(criteria) != 2 or len(accepted) != 2 \
                or [item.get('id') for item in criteria] != [item[0] for item in expected_criteria]:
            raise RuntimeError('Two ordered original mail semantic criteria required')
        for criterion, observed, (criterion_id, evidence_id) in zip(criteria, accepted, expected_criteria):
            decision = json.loads(observed['response'])
            citations = criterion.get('citations')
            if criterion.get('id') != criterion_id or criterion.get('satisfied') is not True \
                    or decision.get('satisfied') is not True or decision.get('citations') != citations \
                    or not isinstance(citations, list) or not citations \
                    or any(not isinstance(item, dict) or item.get('evidenceId') != evidence_id
                           or not isinstance(item.get('quote'), str) for item in citations):
                raise RuntimeError('Original v4 mail Judge criterion differs from its own HTTP response')
