    if request_wire.get('request') != request or post.get('operationId') != operation_id \
            or post.get('requestSha256') != request_digest \
            or request_wire.get('targetId') == original['sourceBinding'].get('target_id') \
            or response_wire.get('targetId') != request_wire.get('targetId') \
            or response_wire.get('version') != 'secureshop-owned-system-diagnostic-http.v1':
        raise RuntimeError('Original command, owned target and executor response must join')
    result = response_wire.get('result', {})
    target_name = 'system-diag-' + request_wire['targetId'].replace('-', '')
    expected_stdout = f'diagnostic-baseline\n{target_name}\n'.encode()
    stdout = base64.b64decode(result.get('stdout', ''), validate=True)
    stderr = base64.b64decode(result.get('stderr', ''), validate=True)
    if response_wire.get('hostname') != target_name \
            or result.get('operationId') != operation_id or result.get('requestSha256') != request_digest \
            or result.get('command') != request['cmd_template'] + ' ' + request['args'] \
            or result.get('executed') is not True or result.get('exitCode') != 0 \
            or result.get('drained') is not True or result.get('timedOut') is not False \
            or result.get('truncated') is not False or result.get('signal') is not None \
            or result.get('encoding') != 'base64' or stdout != expected_stdout or stderr != b'' \
            or result.get('stdoutBytes') != len(stdout) or result.get('stderrBytes') != 0 \
            or result.get('stdoutSha256') != hashlib.sha256(stdout).hexdigest() \
            or result.get('stderrSha256') != hashlib.sha256(stderr).hexdigest():
        raise RuntimeError('Original isolated two-line System output required')
