    if set(assessment) != {'initial', 'post', 'saved', 'judgment', 'contribution',
            'completion', 'workshop', 'judgeTranscript'}:
        raise RuntimeError('Closed canonical diagnostic assessment proof required')
    initial, assessed, saved_assessment = (assessment[key] for key in ('initial', 'post', 'saved'))
    source_ids = {'sessionId': original['sessionId'], 'requestId': original['requestId'],
                  'proposalId': operation_id}
    saved_path = '/agents/admin/assistant/system/diagnostic/assess/' + '/'.join(source_ids.values())
    if initial != {'method': 'GET', 'path': saved_path, 'status': 200,
                   'body': {'completed': False, 'status': 'unconfirmed', 'modelEvaluated': False},
                   'requestBody': None} \
            or assessed.get('method') != 'POST' \
            or assessed.get('path') != '/agents/admin/assistant/system/diagnostic/assess' \
            or assessed.get('status') != 200 or assessed.get('requestBody') != source_ids \
            or assessed.get('body', {}).get('completed') is not True \
            or assessed.get('body', {}).get('replayed') is not False \
            or assessed.get('body', {}).get('judgment', {}).get('verdict') != 'pass' \
            or saved_assessment.get('method') != 'GET' or saved_assessment.get('path') != saved_path \
            or saved_assessment.get('status') != 200 or saved_assessment.get('requestBody') is not None \
            or saved_assessment.get('body') != dict(assessed['body'], replayed=True):
        raise RuntimeError('Physical original assessment POST and canonical saved GET must join')
