    if target.is_symlink() or not target.is_file() or target.stat().st_uid != os.getuid() \
            or target.stat().st_mode & 0o777 != 0o600 or target.stat().st_size > 4096:
        raise RuntimeError('Private owned administrator audit-jobs receipt required')
    receipt = json.loads(target.read_text())
    if (not isinstance(receipt, dict)
            or set(receipt) != set(ADMIN_AUDIT_JOBS_FLAGS) | {'scope', 'actorCalls', 'actorPhases', 'roleTurns', 'jobRuns', 'judgeEvaluations', 'judgeCalls', 'errors'}
            or any(receipt.get(field) is not True for field in ADMIN_AUDIT_JOBS_FLAGS)
            or receipt.get('scope') != ADMIN_AUDIT_JOBS_SCOPE
            or type(receipt.get('roleTurns')) is not int or receipt['roleTurns'] != 2
            or type(receipt.get('jobRuns')) is not int or receipt['jobRuns'] != 2
            or type(receipt.get('actorCalls')) is not int or not 8 <= receipt['actorCalls'] <= 28
            or type(receipt.get('actorPhases')) is not int or not 8 <= receipt['actorPhases'] <= 14
            or receipt['actorCalls'] < receipt['actorPhases']
            or type(receipt.get('judgeEvaluations')) is not int or not 1 <= receipt['judgeEvaluations'] <= 2
            or type(receipt.get('judgeCalls')) is not int or not 1 <= receipt['judgeCalls'] <= 12
            or receipt['judgeCalls'] < receipt['judgeEvaluations']
            or receipt.get('errors') != []):
        raise RuntimeError('Complete administrator audit-jobs assertion and cleanup receipt required')
    return receipt


