def scene_audit_evidence(target, receipt):
    value = scene_audit_private_json(target, 16 * 1024 * 1024)
    if (not isinstance(value, dict) or set(value) != {'scope', 'actualQualification', 'runs',
            'physicalMerchantSave', 'originalSource', 'fences', 'observed'}
            or value.get('scope') != SCENE_AUDIT_SCOPE or value.get('actualQualification') is not False
            or not isinstance(value.get('runs'), dict) or set(value['runs']) != {'vuln', 'fixed'}):
        raise RuntimeError('Original V15 capture envelope required')
    observed = value['observed']
    if (not isinstance(observed, dict) or observed.get('failure') is not None
            or type(observed.get('actorCalls')) is not int or observed['actorCalls'] != receipt['actorCalls']
            or type(observed.get('judgeCalls')) is not int or observed['judgeCalls'] != receipt['judgeCalls']
            or not isinstance(observed.get('configuredJudge'), list) or not observed['configuredJudge']
            or not isinstance(observed.get('judgeTranscripts'), list) or not observed['judgeTranscripts']
            or value.get('originalSource', {}).get('entry', {}).get('id') != receipt['merchantEventId']):
        raise RuntimeError('V15 original source and configured Judge observation required')
    for mode, run in value['runs'].items():
        if not isinstance(run, dict) or run.get('mode') != mode:
            raise RuntimeError('V15 original run mode required')
        saved = run.get('savedResult', {})
        if mode == 'vuln' and saved.get('runId') != receipt['summaryRunId']:
            raise RuntimeError('V15 receipt must identify the captured original run')
        if run.get('artifactRefs') != saved.get('evidence', {}).get('artifacts'):
            raise RuntimeError('V15 captured artifact references changed')
        reads = run.get('artifactReads')
        if not isinstance(reads, dict) or set(reads) != {'effects', 'log', 'sources', 'messages', 'traces'}:
            raise RuntimeError('Complete original V15 artifact reads required')
        for name, read in reads.items():
            ref = run['artifactRefs'].get(name)
            if (not isinstance(read, dict) or not isinstance(ref, dict)
                    or read.get('complete') is not True or read.get('oversized') is not False
                    or type(read.get('observedBytes')) is not int
                    or type(ref.get('bytes')) is not int or not 0 <= ref['bytes'] <= 1024 * 1024
                    or read['observedBytes'] != ref['bytes'] or read.get('bytes') != ref['bytes']
                    or read.get('sha256') != ref.get('sha256') or not isinstance(read.get('base64'), str)):
                raise RuntimeError('Complete bounded V15 artifact reference required')
            try:
                raw = base64.b64decode(read['base64'], validate=True)
            except (ValueError, TypeError) as error:
                raise RuntimeError('Original V15 artifact encoding required') from error
            if len(raw) != ref['bytes'] or hashlib.sha256(raw).hexdigest() != ref.get('sha256'):
                raise RuntimeError('Original V15 artifact digest mismatch')
    # This is capture integrity, not a replacement for the native canonical Judge.
    return {'path': Path(target).name, 'sha256': digest(target), 'bytes': Path(target).stat().st_size,
            'scope': SCENE_AUDIT_SCOPE, 'originalArtifactReads': 10}


