def catalog_page_wire(target, receipt, model_digest):
    target = Path(target)
    if (target.is_symlink() or not target.is_file() or target.stat().st_uid != os.getuid()
            or target.stat().st_nlink != 1 or target.stat().st_mode & 0o777 != 0o600
            or not 0 < target.stat().st_size <= 128 * 1024 * 1024):
        raise RuntimeError('Private original catalog-page model wire required')
    try:
        wire = json.loads(target.read_text())
    except (UnicodeError, ValueError) as error:
        raise RuntimeError('Original catalog-page model wire is invalid') from error
    if (not isinstance(wire, dict) or set(wire) != {'version', 'scope', 'model', 'modelDigest', 'calls', 'turns'}
            or type(wire['version']) is not int or wire['version'] != 1
            or wire['scope'] != CATALOG_PAGE_SCOPE or wire['model'] != OLLAMA_MODEL
            or wire['modelDigest'] != model_digest or not isinstance(wire['calls'], list)
            or not isinstance(wire['turns'], list) or len(wire['turns']) != 8
            or len(wire['calls']) != receipt['actorCalls'] or not 16 <= len(wire['calls']) <= 37
            or receipt['roleTurns'] != 8 or receipt['judgeCalls'] != 0):
        raise RuntimeError('Closed catalog-page original wire required')

    def sha(value):
        return isinstance(value, str) and len(value) == 64 and all(ch in '0123456789abcdef' for ch in value)

    def uuid(value):
        return isinstance(value, str) and re.fullmatch(
            r'[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}', value) is not None

    def decode(value):
        try:
            return json.loads(value)
        except (TypeError, ValueError) as error:
            raise RuntimeError('Catalog-page original model JSON invalid') from error

    for index, call in enumerate(wire['calls'], 1):
        if (not isinstance(call, dict) or call.get('index') != index or call.get('model') != OLLAMA_MODEL
                or call.get('status') != 200 or call.get('error')
                or call.get('responseComplete') is not True
                or call.get('responseCaptureTruncated') is not False
                or call.get('terminalReason') != 'end'
                or call.get('responseObservedBytes') != call.get('responseBytes')):
            raise RuntimeError('Catalog-page actor wire incomplete')
        for part, maximum in (('request', 262144), ('response', 4194304)):
            value = call.get(part)
            if not isinstance(value, str):
                raise RuntimeError('Catalog-page original wire body missing')
            body = value.encode('utf-8')
            if (not 0 < len(body) <= maximum or call.get(part + 'Bytes') != len(body)
                    or call.get(part + 'Sha256') != hashlib.sha256(body).hexdigest()):
                raise RuntimeError('Catalog-page original wire digest mismatch')
        request = decode(call['request'])
        if (not isinstance(request, dict) or request.get('model') != OLLAMA_MODEL
                or not isinstance(request.get('messages'), list)
                or request.get('mocked') is True or request.get('fallback') is True):
            raise RuntimeError('Catalog-page raw request model or messages mismatch')
        response = [decode(line) for line in call['response'].splitlines() if line.strip()]
        if not response or any(not isinstance(row, dict) for row in response):
            raise RuntimeError('Catalog-page raw response missing')

    seen_requests = set()
    expected_roles = ('customer', 'customer', 'customer', 'merchant', 'merchant', 'merchant',
                      'merchant', 'merchant')
    next_wire = 1
    for position, (turn, role) in enumerate(zip(wire['turns'], expected_roles)):
        if (not isinstance(turn, dict)
                or set(turn) != {'role', 'sessionId', 'requestId', 'request', 'binding',
                                 'saved', 'receipt', 'logicalCalls', 'wireStart', 'wireEnd',
                                 'sourceEnvelope'}
                or turn['role'] != role or not uuid(turn['sessionId']) or not uuid(turn['requestId'])
                or (turn['sessionId'], turn['requestId']) in seen_requests
                or turn['wireStart'] != next_wire or type(turn['wireEnd']) is not int
                or not turn['wireStart'] <= turn['wireEnd'] <= len(wire['calls'])
                or turn['wireEnd'] - turn['wireStart'] + 1 > 10):
            raise RuntimeError('Catalog-page turns or wire spans differ')
        seen_requests.add((turn['sessionId'], turn['requestId']))
        next_wire = turn['wireEnd'] + 1
        request, binding, saved, result = (turn[key] for key in ('request', 'binding', 'saved', 'receipt'))
        logical = turn['logicalCalls']
        if (not isinstance(request, dict) or request.get('sessionId') != turn['sessionId']
                or request.get('requestId') != turn['requestId']
                or not isinstance(request.get('message'), str) or not request['message']
                or not isinstance(binding, dict)
                or set(binding) != {'request_hash', 'journal_hash', 'request_version',
                                    'envelope_sha256', 'target_id', 'persona_id'}
                or binding['request_hash'] != binding['journal_hash']
                or not sha(binding['request_hash']) or not sha(binding['envelope_sha256'])
                or type(binding['request_version']) is not int or binding['request_version'] != 1
                or not uuid(binding['target_id']) or type(binding['persona_id']) is not int
                or binding['persona_id'] < 1
                or not isinstance(saved, dict) or saved.get('stopReason') != 'end_turn'
                or not isinstance(saved.get('hops'), list) or len(saved['hops']) != 1
                or not isinstance(result, dict) or result.get('status') != 'completed'
                or result.get('replayed') is not True
                or result.get('sessionId') != turn['sessionId']
                or result.get('requestId') != turn['requestId']
                or result.get('hops') != saved['hops']
                or not isinstance(logical, list) or not 2 <= len(logical) <= 5
                or len(logical) > turn['wireEnd'] - turn['wireStart'] + 1):
            raise RuntimeError('Catalog-page saved source or logical actor mismatch')
        tool = 'catalog.details' if position == 2 else (
            'catalog.search' if role == 'customer' else 'merchant.catalog_search')
        hops = [hop for hop in saved['hops'] if isinstance(hop, dict) and hop.get('tool') == tool
                and not hop.get('error') and hop.get('result', {}).get('isError') is not True]
        if len(hops) != 1 or not any(tool in call.get('tools', []) for call in logical):
            raise RuntimeError('Catalog-page saved selected tool lacks model decision')
        if (any(not isinstance(call, dict) or call.get('provider') != 'ollama'
                or call.get('model') != OLLAMA_MODEL or call.get('method') not in ('chat', 'finalResponse')
                or not isinstance(call.get('tools'), list) for call in logical)
                or not any(call.get('stopReason') == 'end_turn' for call in logical)):
            raise RuntimeError('Catalog-page logical model provenance invalid')
        span = wire['calls'][turn['wireStart'] - 1:turn['wireEnd']]
        def raw_decision(call):
            frames = [decode(line) for line in call['response'].splitlines() if line.strip()]
            content = ''.join((frame.get('message') or {}).get('content', '') for frame in frames)
            try:
                decision = decode(content)
            except RuntimeError:
                decision = None
            return decision if isinstance(decision, dict) else None
        def raw_selected(call):
            decision = raw_decision(call)
            selected = decision.get('tool_calls', []) if decision else []
            if isinstance(selected, list) and any(isinstance(item, dict)
                and isinstance(item.get('agent'), str) and isinstance(item.get('tool'), str)
                and item['agent'] + '.' + item['tool'] == tool
                and item.get('args') == hops[0].get('params') for item in selected):
                return True
            frames = [decode(line) for line in call['response'].splitlines() if line.strip()]
            for frame in frames:
                message = frame.get('message') if isinstance(frame, dict) else None
                native = message.get('tool_calls') if isinstance(message, dict) else None
                if not isinstance(native, list):
                    continue
                for item in native:
                    if not isinstance(item, dict):
                        continue
                    function = item.get('function') if isinstance(item.get('function'), dict) else {}
                    args = function.get('arguments', item.get('args'))
                    if isinstance(args, str):
                        try:
                            args = decode(args)
                        except RuntimeError:
                            continue
                    if (function.get('name', item.get('name')) == tool
                            and args == hops[0].get('params')):
                        return True
            return False
        if (not any(raw_selected(call) for call in span)
                or not any((raw_decision(call) or {}).get('answer') == saved.get('text')
                    for call in span)):
            raise RuntimeError('Catalog-page raw model wire is not bound to saved turn')
        metadata = saved.get('taskMetadata')
        source = metadata.get('customerChat' if role == 'customer' else 'roleChat', {}) if isinstance(metadata, dict) else {}
        if (not isinstance(source, dict) or source.get('envelopeSha256') != binding['envelope_sha256']
                or source.get('targetId') != binding['target_id']
                or result.get('modeCapability') != saved.get('modeCapability')):
            raise RuntimeError('Catalog-page durable envelope or mode differs')
        expected_envelope = {'version': 1}
        if role == 'merchant':
            expected_envelope['role'] = 'merchant'
        expected_envelope.update(sceneId=source.get('sceneId'),
            sceneGeneration=source.get('sceneGeneration'), targetId=binding['target_id'])
        if role == 'customer':
            expected_envelope['requestId'] = turn['requestId']
        expected_envelope['message'] = request['message']
        if role == 'merchant' and request.get('catalogContinuation') is not None:
            expected_envelope['catalogContinuation'] = request['catalogContinuation']
        if request.get('selection') is not None:
            selection = request['selection']
            if role == 'customer':
                prior_card = wire['turns'][position - 1]['receipt']['cards'][0] if position % 3 == 2 else None
                expected_envelope['selection'] = {'kind': prior_card.get('kind') if isinstance(prior_card, dict) else None,
                    **selection}
            else:
                expected_envelope['selection'] = selection
        if role == 'customer' and request.get('catalogContinuation') is not None:
            expected_envelope['catalogContinuation'] = request['catalogContinuation']
        original_envelope = json.dumps(expected_envelope, separators=(',', ':'), ensure_ascii=False)
        if (not isinstance(turn['sourceEnvelope'], str)
                or turn['sourceEnvelope'] != original_envelope
                or not isinstance(source.get('sceneId'), str)
                or type(source.get('sceneGeneration')) is not int
                or not all(any(isinstance(message, dict) and message.get('role') == 'user'
                    and message.get('content') == original_envelope
                    for message in decode(call['request']).get('messages', [])) for call in span)):
            raise RuntimeError('Catalog-page original model prompt differs from protected bound source')
        if position in (0, 1, 3, 4, 6):
            page = source.get('catalogPageSource') if isinstance(source, dict) else None
            total, size, count = ((15, 12, 12 if position == 0 else 3)
                                  if role == 'customer' else
                                  (1, 5, 1) if position == 6 else
                                  (7, 5, 5 if position == 3 else 2))
            prior = wire['turns'][position - 1] if position in (1, 4) else None
            has_more = position in (0, 3)
            if (not isinstance(page, dict) or page.get('version') != 1
                    or (page.get('status') != 'active' if role == 'customer'
                        else page.get('status') != 'inactive' if position == 6
                        else page.get('status') not in ('active', 'all'))
                    or page.get('total') != total
                    or page.get('returnedCount') != count
                    or page.get('sourceRequestId') != (prior['requestId'] if prior else None)
                    or page.get('afterCursor') != (prior['saved']['taskMetadata'][
                        'customerChat' if role == 'customer' else 'roleChat']['catalogPageSource']['nextCursor']
                        if prior else None)
                    or (page.get('nextCursor') is None) == has_more
                    or result.get('catalogPage') != {'version': 1, 'total': total,
                                                     'pageSize': size, 'returnedCount': count,
                                                     'hasMore': has_more}
                    or not isinstance(result.get('cards'), list) or len(result['cards']) != count
                    or (prior is None and not (
                        hops[0].get('params') == {'search': page.get('search')}
                        and page.get('status') == 'active'
                        or role == 'merchant' and hops[0].get('params') == {
                            'search': page.get('search'), 'status': page.get('status')}))
                    or (prior is not None and (request.get('catalogContinuation') != {
                        'intent': 'catalog_next', 'sourceRequestId': prior['requestId']}
                        or hops[0].get('params') != {}
                        or page.get('status') != prior['saved']['taskMetadata'][
                            'customerChat' if role == 'customer' else 'roleChat'][
                                'catalogPageSource']['status']
                        or page.get('search') != prior['saved']['taskMetadata'][
                            'customerChat' if role == 'customer' else 'roleChat'][
                                'catalogPageSource']['search']))):
                raise RuntimeError('Catalog-page source cursor or public page differs')
            content = hops[0].get('result', {}).get('content')
            observed = decode(content[0].get('text')) if isinstance(content, list) and len(content) == 1 else None
            if (not isinstance(observed, dict) or observed.get('total') != total
                    or not isinstance(observed.get('products'), list)
                    or len(observed['products']) != count
                    or (role == 'customer' and observed.get('cards') != result['cards'])
                    or (role == 'merchant' and [choice.get('card') for choice in source.get('choices', [])]
                        != result['cards'])):
                raise RuntimeError('Catalog-page original tool observation differs')
            if (position == 0 and (not uuid(page.get('nextCursor'))
                    or page['nextCursor'] != result['cards'][-1].get('choiceId'))
                    or position == 3 and (type(page.get('nextCursor')) is not int
                        or page['nextCursor'] != observed['products'][-1].get('id')
                        or page['nextCursor'] != source['choices'][-1].get('sourceId'))):
                raise RuntimeError('Catalog-page next cursor differs from last owned choice')
            if position == 6 and (result['cards'][0].get('readOnly') is not True
                    or observed['products'][0].get('status') != 'inactive'
                    or type(observed['products'][0].get('id')) is not int
                    or observed['products'][0]['id'] != source['choices'][0].get('sourceId')):
                raise RuntimeError('Inactive merchant discovery is not a read-only owned choice')
        else:
            prior = wire['turns'][position - 1]
            selected = request.get('selection')
            if (not isinstance(selected, dict) or selected.get('choiceId') != prior['receipt']['cards'][0].get('choiceId')
                    or hops[0].get('params', {}).get('choiceId') != selected['choiceId']
                    or result.get('catalogPage') not in (None,)):
                raise RuntimeError('Catalog-page selected detail differs from page two')
            if position == 7:
                content = hops[0].get('result', {}).get('content')
                observed = decode(content[0].get('text')) if isinstance(content, list) and len(content) == 1 else None
                prior_content = prior['saved']['hops'][0].get('result', {}).get('content')
                prior_observed = decode(prior_content[0].get('text')) if isinstance(prior_content, list) and len(prior_content) == 1 else None
                if (prior['receipt']['cards'][0].get('readOnly') is not True
                        or not isinstance(result.get('cards'), list) or len(result['cards']) != 1
                        or result['cards'][0].get('readOnly') is not True
                        or not isinstance(observed, dict) or not isinstance(prior_observed, dict)
                        or not isinstance(observed.get('products'), list) or len(observed['products']) != 1
                        or not isinstance(prior_observed.get('products'), list) or len(prior_observed['products']) != 1
                        or observed['products'][0].get('id') != prior_observed['products'][0].get('id')
                        or observed['products'][0].get('status') != 'inactive'):
                    raise RuntimeError('Inactive merchant detail differs from read-only discovery')
    if next_wire != len(wire['calls']) + 1:
        raise RuntimeError('Catalog-page original model wire has unowned attempts')
    return wire


