def c31_receipt(result_path, terminal_wire_path):
    def private_json(path, limit):
        path = Path(path)
        if path.is_symlink() or not path.is_file() or path.stat().st_uid != os.getuid() \
                or path.stat().st_mode & 0o777 != 0o600 or not 0 < path.stat().st_size <= limit:
            raise RuntimeError('Private owned Persona Inbox evidence required')
        return json.loads(path.read_text())

    result = private_json(result_path, 1024 * 1024)
    wire = private_json(terminal_wire_path, 128 * 1024 * 1024)
    expected_result = {'status', 'actualQualification', 'stage', 'poolsClosed',
                       'pendingOuterOwnershipVerification', 'result'}
    expected_inner = {'actualModelProof', 'genuineCredit', 'qualifiedObjectiveIds',
                      'qualification', 'actorCalls', 'judgeCalls', 'actualQualification',
                      'scope', 'resetVerified', 'siblingVerified'}
    if (not isinstance(result, dict) or set(result) != expected_result
            or result['status'] != 'passed' or result['actualQualification'] is not False
            or result['stage'] != 'standalone-persona-rendered-inbox'
            or result['poolsClosed'] is not True
            or result['pendingOuterOwnershipVerification'] is not True
            or not isinstance(result['result'], dict) or set(result['result']) != expected_inner):
        raise RuntimeError('Complete unpromoted Persona Inbox child receipt required')
    inner = result['result']
    if (inner['actualModelProof'] is not True or inner['qualification'] != 'qualified'
            or type(inner['genuineCredit']) is not int or inner['genuineCredit'] != 3
            or inner['qualifiedObjectiveIds'] != list(C31_OBJECTIVES)
            or inner['actualQualification'] is not False or inner['scope'] != C31_SCOPE
            or inner['resetVerified'] is not True or inner['siblingVerified'] is not True
            or type(inner['actorCalls']) is not int or not 2 <= inner['actorCalls'] <= 32
            or type(inner['judgeCalls']) is not int or not 3 <= inner['judgeCalls'] <= 48):
        raise RuntimeError('Persona Inbox actor, Judge, or objective evidence incomplete')
    expected_wire = {'version', 'model', 'digest', 'calls', 'metadataProbes', 'counts', 'phaseCounts',
                     'externalAttempts', 'physicalPending', 'closed', 'failed',
                     'originalFailure', 'recoveryAdmission'}
    if (not isinstance(wire, dict) or set(wire) != expected_wire
            or wire['version'] != 'inbox-actual-wire-v1' or wire['model'] != OLLAMA_MODEL
            or wire['digest'] != C31_MODEL_SHA256 or wire['closed'] is not True
            or wire['failed'] is not False or wire['originalFailure'] is not None
            or wire['recoveryAdmission'] is not None or type(wire['physicalPending']) is not int
            or wire['physicalPending'] != 0 or not isinstance(wire['calls'], list)
            or not isinstance(wire['metadataProbes'], list)
            or not isinstance(wire['counts'], dict)
            or set(wire['counts']) != {'tags', 'actor', 'judge'}
            or not isinstance(wire['phaseCounts'], dict)
            or set(wire['phaseCounts']) != {'advisory', 'enforced'}):
        raise RuntimeError('Complete closed Persona Inbox model wire required')
    counts = wire['counts']
    if (any(type(counts[name]) is not int for name in counts)
            or counts['tags'] != 1 + len(wire['metadataProbes'])
            or not 0 <= len(wire['metadataProbes']) <= 20
            or counts['actor'] != inner['actorCalls']
            or counts['judge'] != inner['judgeCalls']
            or type(wire['externalAttempts']) is not int
            or wire['externalAttempts'] != len(wire['calls']) + len(wire['metadataProbes'])
            or len(wire['calls']) != 1 + counts['actor'] + counts['judge']
            or not 6 <= wire['externalAttempts'] <= 81):
        raise RuntimeError('Persona Inbox model wire counts mismatch')
    phase = wire['phaseCounts']
    for name in ('advisory', 'enforced'):
        row = phase[name]
        if (not isinstance(row, dict) or set(row) != {'actor', 'judge'}
                or any(type(row[key]) is not int for key in row)
                or not 1 <= row['actor'] <= 16
                or not 1 <= row['judge'] <= (32 if name == 'advisory' else 16)):
            raise RuntimeError('Persona Inbox model phase counts invalid')
    if (sum(phase[name]['actor'] for name in phase) != counts['actor']
            or sum(phase[name]['judge'] for name in phase) != counts['judge']):
        raise RuntimeError('Persona Inbox model phase counts mismatch')
    observed = {'tags': 0, 'actor': 0, 'judge': 0}
    phase_observed = {name: {'actor': 0, 'judge': 0} for name in phase}
    for index, row in enumerate(wire['calls']):
        if (not isinstance(row, dict) or set(row) != {'index', 'caseId', 'role', 'path',
                'request', 'requestSha256', 'status', 'httpStatus', 'response', 'responseSha256'}
                or type(row['index']) is not int or row['index'] != index
                or row['role'] not in observed or row['status'] != 'returned'
                or type(row['httpStatus']) is not int or row['httpStatus'] != 200
                or not isinstance(row['request'], str) or not isinstance(row['response'], str)
                or row['requestSha256'] != hashlib.sha256(row['request'].encode()).hexdigest()
                or row['responseSha256'] != hashlib.sha256(row['response'].encode()).hexdigest()):
            raise RuntimeError('Persona Inbox model wire call invalid')
        role, case = row['role'], row['caseId']
        if role == 'tags':
            if index != 0 or case is not None or row['path'] != '/api/tags' or row['request'] != '':
                raise RuntimeError('Persona Inbox model inventory call invalid')
            try:
                models = json.loads(row['response'])['models']
            except (ValueError, TypeError, KeyError) as error:
                raise RuntimeError('Persona Inbox model inventory identity invalid') from error
            if (not isinstance(models, list) or not any(isinstance(item, dict)
                    and item.get('name') == OLLAMA_MODEL and item.get('digest') == C31_MODEL_SHA256
                    for item in models)):
                raise RuntimeError('Persona Inbox model inventory identity invalid')
        elif case not in phase or row['path'] != '/api/chat' or not row['request']:
            raise RuntimeError('Persona Inbox actor or Judge call invalid')
        else:
            phase_observed[case][role] += 1
        observed[role] += 1
    for index, row in enumerate(wire['metadataProbes']):
        if (not isinstance(row, dict) or set(row) != {'index', 'caseId', 'role', 'path',
                'request', 'requestSha256', 'status', 'httpStatus', 'response', 'responseSha256'}
                or type(row['index']) is not int or row['index'] != index
                or row['caseId'] not in (None, 'advisory', 'enforced')
                or row['role'] != 'tags' or row['path'] != '/api/tags'
                or row['request'] != '' or row['requestSha256'] != hashlib.sha256(b'').hexdigest()
                or row['status'] != 'returned' or type(row['httpStatus']) is not int
                or row['httpStatus'] != 200 or not isinstance(row['response'], str)
                or len(row['response'].encode()) > 65536
                or row['responseSha256'] != hashlib.sha256(row['response'].encode()).hexdigest()):
            raise RuntimeError('Persona Inbox metadata probe invalid')
        try:
            models = json.loads(row['response'])['models']
        except (ValueError, TypeError, KeyError) as error:
            raise RuntimeError('Persona Inbox metadata identity invalid') from error
        if (not isinstance(models, list) or not any(isinstance(item, dict)
                and item.get('name') == OLLAMA_MODEL and item.get('digest') == C31_MODEL_SHA256
                for item in models)):
            raise RuntimeError('Persona Inbox metadata identity invalid')
    if (observed != {'tags': 1, 'actor': counts['actor'], 'judge': counts['judge']}
            or phase_observed != phase):
        raise RuntimeError('Persona Inbox model wire rows mismatch')
    return result


